/* Agrikranti - ICAR T-3 & T-4 Agriculture 30-Day Full Mock Test Series (ASRB 2026-27).
   Each test = Paper I (100 Q, 60 min, +1/-0.25) + Paper II (100 Q, 120 min, +3/-1), separate attempts.
   Test 01 free. Tests 02-30 paid (pack 'icarts', Rs 149): encrypted files in tests/icar/, released by 'rel' date (IST) once ready.
   Paper II follows the 20 units of ICAR OM F.No. TS-19(6)/2024-Estt.IV dt 28.09.2026. Unit-wise counts are Agrikranti's own blueprint, not official. */
window.TESTS=(window.TESTS||[]).concat([{"id": "ICAR01-P1", "series": "icar-t3t4", "title": "Test 01 Paper I - Paper I (Prelims): GK, English, Quant, Gen. Agriculture (FREE)", "free": true, "rel": "2026-11-16", "fixed": true, "secs": [{"n": "GK", "f": 0}, {"n": "English", "f": 25}, {"n": "Quant", "f": 50}, {"n": "Gen. Agri", "f": 75}], "dur": 60, "mpq": 1, "neg": 0.25, "questions": [{"q": "ओज़ोन परत मुख्य रूप से वायुमंडल की किस परत में पाई जाती है?\nThe ozone layer is mainly found in which layer of the atmosphere?", "o": ["क्षोभमंडल / Troposphere", "मध्यमंडल / Mesosphere", "तापमंडल / Thermosphere", "समतापमंडल / Stratosphere"], "a": 3, "e": "ओज़ोन परत समतापमंडल (लगभग 15-35 km) में है और पराबैंगनी (UV-B) किरणों को सोखती है।\nThe ozone layer lies in the stratosphere (about 15-35 km) and absorbs UV-B radiation.", "s": "GS", "lv": "Easy", "src": "NCERT textbooks (Science/Geography/History, Classes VI-XII) - Class XI Geography, Ch. Composition and Structure of Atmosphere", "cls": "New - PYQ pattern"}, {"q": "अम्लीय वर्षा (Acid rain) के लिए मुख्य रूप से कौन-सी गैस उत्तरदायी है?\nWhich gas is a major cause of acid rain?", "o": ["कार्बन डाइऑक्साइड / Carbon dioxide", "मीथेन / Methane", "हीलियम / Helium", "सल्फर डाइऑक्साइड / Sulphur dioxide"], "a": 3, "e": "SO2 और NOx जल से मिलकर सल्फ्यूरिक व नाइट्रिक अम्ल बनाते हैं, जो अम्लीय वर्षा का कारण हैं।\nSO2 and NOx form sulphuric and nitric acids in rain water, causing acid rain.", "s": "GS", "lv": "Easy", "src": "NCERT textbooks (Science/Geography/History, Classes VI-XII) - Class XI Chemistry, Environmental Chemistry", "cls": "New - PYQ pattern"}, {"q": "सूर्य के प्रकाश की उपस्थिति में त्वचा में कौन-सा विटामिन बनता है?\nWhich vitamin is synthesised in the skin in the presence of sunlight?", "o": ["विटामिन D / Vitamin D", "विटामिन A / Vitamin A", "विटामिन C / Vitamin C", "विटामिन K / Vitamin K"], "a": 0, "e": "UV-B किरणें त्वचा के 7-डीहाइड्रोकोलेस्ट्रॉल को विटामिन D3 में बदलती हैं।\nUV-B converts 7-dehydrocholesterol in skin into vitamin D3.", "s": "GS", "lv": "Easy", "src": "NCERT Biology; ICMR-NIN, Dietary Guidelines for Indians (2024)", "cls": "New - PYQ pattern"}, {"q": "आकाश का रंग नीला क्यों दिखाई देता है?\nWhy does the sky appear blue?", "o": ["प्रकाश के परावर्तन से / Reflection of light", "प्रकाश के अपवर्तन से / Refraction of light", "पूर्ण आंतरिक परावर्तन से / Total internal reflection", "प्रकाश के प्रकीर्णन से / Scattering of light"], "a": 3, "e": "वायु के अणु छोटी तरंगदैर्ध्य (नीला प्रकाश) को अधिक प्रकीर्णित करते हैं (Rayleigh scattering)।\nAir molecules scatter shorter (blue) wavelengths more strongly - Rayleigh scattering.", "s": "GS", "lv": "Easy", "src": "NCERT textbooks (Science/Geography/History, Classes VI-XII) - Class X Science, The Human Eye and the Colourful World", "cls": "New - PYQ pattern"}, {"q": "बेकिंग सोडा का रासायनिक नाम क्या है?\nWhat is the chemical name of baking soda?", "o": ["सोडियम बाइकार्बोनेट / Sodium hydrogen carbonate", "सोडियम कार्बोनेट / Sodium carbonate", "सोडियम क्लोराइड / Sodium chloride", "कैल्शियम कार्बोनेट / Calcium carbonate"], "a": 0, "e": "बेकिंग सोडा = NaHCO3 (सोडियम हाइड्रोजन कार्बोनेट); वाशिंग सोडा = Na2CO3.10H2O।\nBaking soda is NaHCO3; washing soda is Na2CO3.10H2O.", "s": "GS", "lv": "Easy", "src": "NCERT textbooks (Science/Geography/History, Classes VI-XII) - Class X Science, Acids, Bases and Salts", "cls": "New - PYQ pattern"}, {"q": "मॉन्ट्रियल प्रोटोकॉल (1987) किससे संबंधित है?\nThe Montreal Protocol (1987) deals with", "o": ["ओज़ोन क्षयकारी पदार्थों का नियंत्रण / Control of ozone-depleting substances", "जैव विविधता संरक्षण / Biodiversity conservation", "आर्द्रभूमि संरक्षण / Wetland conservation", "खतरनाक अपशिष्ट का सीमापार परिवहन / Transboundary movement of hazardous waste"], "a": 0, "e": "मॉन्ट्रियल प्रोटोकॉल CFC जैसे ओज़ोन क्षयकारी पदार्थों को चरणबद्ध रूप से समाप्त करता है। रामसर = आर्द्रभूमि, बेसल = खतरनाक अपशिष्ट।\nThe Montreal Protocol phases out ozone-depleting substances such as CFCs. Ramsar = wetlands; Basel = hazardous waste.", "s": "GS", "lv": "Moderate", "src": "UNEP Ozone Secretariat (ozone.unep.org)", "cls": "New - PYQ pattern"}, {"q": "नवंबर 2025 में UNFCCC का COP30 सम्मेलन किस शहर में आयोजित हुआ?\nIn November 2025, COP30 of the UNFCCC was held in which city?", "o": ["बाकू / Baku", "दुबई / Dubai", "शर्म अल-शेख / Sharm el-Sheikh", "बेलेम / Belem"], "a": 3, "e": "COP30 (नवंबर 2025) ब्राज़ील के बेलेम (अमेज़न क्षेत्र) में हुआ। COP29 = बाकू (2024), COP28 = दुबई (2023), COP27 = शर्म अल-शेख (2022)।\nCOP30 (Nov 2025) was held at Belem, Brazil. COP29 Baku, COP28 Dubai, COP27 Sharm el-Sheikh. (Fact as on Nov 2026)", "s": "GS", "lv": "Moderate", "src": "UNFCCC (unfccc.int) - COP30 Belem", "cls": "New - PYQ pattern"}, {"q": "नवंबर 2026 की स्थिति में सचिव (DARE) एवं महानिदेशक, ICAR कौन हैं?\nAs of November 2026, who is the Secretary (DARE) and Director General, ICAR?", "o": ["डॉ. हिमांशु पाठक / Dr Himanshu Pathak", "डॉ. त्रिलोचन महापात्र / Dr Trilochan Mohapatra", "डॉ. एम. एल. जाट / Dr M. L. Jat", "डॉ. राघवेंद्र भट्टा / Dr Raghavendra Bhatta"], "a": 2, "e": "डॉ. मांगी लाल जाट सचिव DARE व DG ICAR हैं। डॉ. हिमांशु पाठक अब ICRISAT के DG हैं; डॉ. राघवेंद्र भट्टा DDG (पशु विज्ञान) हैं।\nDr Mangi Lal Jat is Secretary DARE & DG ICAR. Dr Himanshu Pathak is now DG, ICRISAT; Dr Raghavendra Bhatta is DDG (Animal Science). (Fact as on 1 Nov 2026)", "s": "GS", "lv": "Moderate", "src": "ICAR news, 1 Nov 2026 (icar.org.in/index.php/hi/node/27292); ICAR news, 30 Oct 2026 (node/27283)", "cls": "New - PYQ pattern"}, {"q": "मई 2025 में ICAR द्वारा जारी भारत की पहली जीनोम-संपादित (Genome-edited) धान किस्मों में से एक कौन-सी है?\nWhich one of the following is among India's first genome-edited rice varieties released by ICAR in May 2025?", "o": ["पूसा बासमती 1121 / Pusa Basmati 1121", "DRR धान 100 (कमला) / DRR Dhan 100 (Kamala)", "स्वर्णा सब-1 / Swarna Sub1", "पूसा 44 / Pusa 44"], "a": 1, "e": "4 मई 2025 को 'DRR धान 100 (कमला)' और 'पूसा DST राइस 1' जारी की गईं - दोनों SDN-1/SDN-2 जीनोम एडिटिंग से विकसित।\nOn 4 May 2025, 'DRR Dhan 100 (Kamala)' and 'Pusa DST Rice 1' were released, developed through genome editing (SDN-1/SDN-2).", "s": "GS", "lv": "Moderate", "src": "ICAR press release, 4 May 2025 (icar.org.in)", "cls": "New - PYQ pattern"}, {"q": "भारत में 'राष्ट्रीय अंतरिक्ष दिवस' (National Space Day) किस तिथि को मनाया जाता है?\nIndia's National Space Day is observed on", "o": ["14 जुलाई / 14 July", "15 अगस्त / 15 August", "2 अक्टूबर / 2 October", "23 अगस्त / 23 August"], "a": 3, "e": "चंद्रयान-3 के विक्रम लैंडर ने 23 अगस्त 2023 को चंद्रमा के दक्षिणी ध्रुव के पास soft landing की; इसी की याद में 23 अगस्त राष्ट्रीय अंतरिक्ष दिवस है।\nChandrayaan-3's Vikram lander soft-landed near the lunar south pole on 23 Aug 2023; hence 23 August is National Space Day.", "s": "GS", "lv": "Easy", "src": "ISRO (isro.gov.in); PIB release on National Space Day", "cls": "New - PYQ pattern"}, {"q": "संयुक्त राष्ट्र ने वर्ष 2025 को कौन-सा अंतरराष्ट्रीय वर्ष घोषित किया था?\nThe United Nations declared 2025 as the International Year of", "o": ["मिलेट्स / Millets", "दलहन / Pulses", "सहकारिता / Cooperatives", "मृदा / Soils"], "a": 2, "e": "2025 = अंतरराष्ट्रीय सहकारिता वर्ष (थीम: Cooperatives Build a Better World)। 2023 = मिलेट्स, 2016 = दलहन, 2015 = मृदा।\n2025 = International Year of Cooperatives. 2023 Millets, 2016 Pulses, 2015 Soils.", "s": "GS", "lv": "Moderate", "src": "United Nations (un.org/en/observances/international-years)", "cls": "New - PYQ pattern"}, {"q": "ASRB की 11 नवंबर 2026 की अधिसूचना में ICAR T-3 व T-4 के कुल कितने पद घोषित हैं?\nHow many total posts of ICAR T-3 and T-4 were notified by ASRB on 11 November 2026?", "o": ["1,254", "139", "641", "1,393"], "a": 3, "e": "कुल 1,393 पद: T-3 (ICAR संस्थान) 1,254 + T-4 (KVK) 139।\nTotal 1,393 posts: T-3 (ICAR institutes) 1,254 + T-4 (KVKs) 139.", "s": "GS", "lv": "Easy", "src": "ASRB Advt. F.No. 2(2)/2025-Exam dated 11.11.2026 (asrb.gov.in)", "cls": "New - PYQ pattern"}, {"q": "प्लासी का युद्ध किस वर्ष लड़ा गया?\nThe Battle of Plassey was fought in", "o": ["1764", "1757", "1857", "1761"], "a": 1, "e": "प्लासी (1757): रॉबर्ट क्लाइव ने सिराजुद्दौला को हराया। बक्सर = 1764, पानीपत तृतीय = 1761।\nPlassey (1757): Robert Clive defeated Siraj-ud-Daulah. Buxar 1764; Third Panipat 1761.", "s": "GS", "lv": "Easy", "src": "NCERT textbooks (Science/Geography/History, Classes VI-XII) - Class VIII History, From Trade to Territory", "cls": "New - PYQ pattern"}, {"q": "गांधीजी का चंपारण सत्याग्रह (1917) किस फसल की खेती से संबंधित था?\nGandhiji's Champaran Satyagraha (1917) was related to the cultivation of", "o": ["कपास / Cotton", "गन्ना / Sugarcane", "अफ़ीम / Opium", "नील / Indigo"], "a": 3, "e": "चंपारण (बिहार) में किसानों को 'तिनकठिया' प्रथा के तहत नील उगाने को मजबूर किया जाता था।\nIn Champaran (Bihar), peasants were forced to grow indigo under the 'tinkathia' system.", "s": "GS", "lv": "Easy", "src": "NCERT textbooks (Science/Geography/History, Classes VI-XII) - Class XII History, Mahatma Gandhi and the Nationalist Movement", "cls": "New - PYQ pattern"}, {"q": "भारतीय राष्ट्रीय कांग्रेस की स्थापना किस वर्ष हुई?\nThe Indian National Congress was founded in", "o": ["1885", "1857", "1905", "1920"], "a": 0, "e": "INC की स्थापना 1885 में ए.ओ. ह्यूम ने की; पहला अधिवेशन बॉम्बे में, अध्यक्ष डब्ल्यू.सी. बनर्जी।\nINC was founded in 1885 by A.O. Hume; first session at Bombay presided by W.C. Bonnerjee.", "s": "GS", "lv": "Easy", "src": "NCERT textbooks (Science/Geography/History, Classes VI-XII) - Class VIII History, The Making of the National Movement", "cls": "New - PYQ pattern"}, {"q": "हड़प्पा सभ्यता का कौन-सा स्थल गोदीबाड़ा (Dockyard) के लिए प्रसिद्ध है?\nWhich Harappan site is famous for its dockyard?", "o": ["मोहनजोदड़ो / Mohenjo-daro", "लोथल / Lothal", "कालीबंगा / Kalibangan", "राखीगढ़ी / Rakhigarhi"], "a": 1, "e": "लोथल (गुजरात) में ईंटों से बना गोदीबाड़ा मिला है। कालीबंगा = जुते खेत के साक्ष्य; मोहनजोदड़ो = महान स्नानागार।\nLothal (Gujarat) has a brick dockyard. Kalibangan = ploughed field; Mohenjo-daro = Great Bath.", "s": "GS", "lv": "Moderate", "src": "NCERT textbooks (Science/Geography/History, Classes VI-XII) - Class XII History, Bricks, Beads and Bones", "cls": "New - PYQ pattern"}, {"q": "भारत की सबसे लंबी अंतरराष्ट्रीय स्थलीय सीमा किस देश के साथ है?\nIndia shares its longest international land border with", "o": ["चीन / China", "पाकिस्तान / Pakistan", "नेपाल / Nepal", "बांग्लादेश / Bangladesh"], "a": 3, "e": "भारत-बांग्लादेश सीमा लगभग 4,096.7 km है; चीन लगभग 3,488 km, पाकिस्तान लगभग 3,323 km।\nIndia-Bangladesh border is about 4,096.7 km; China about 3,488 km; Pakistan about 3,323 km.", "s": "GS", "lv": "Moderate", "src": "Ministry of Home Affairs, Department of Border Management (mha.gov.in)", "cls": "New - PYQ pattern"}, {"q": "कर्क रेखा (Tropic of Cancer) निम्नलिखित में से किस राज्य से नहीं गुजरती?\nThe Tropic of Cancer does NOT pass through which state?", "o": ["झारखंड / Jharkhand", "त्रिपुरा / Tripura", "मिज़ोरम / Mizoram", "ओडिशा / Odisha"], "a": 3, "e": "कर्क रेखा 8 राज्यों से गुजरती है: गुजरात, राजस्थान, मध्य प्रदेश, छत्तीसगढ़, झारखंड, पश्चिम बंगाल, त्रिपुरा, मिज़ोरम। ओडिशा इसमें नहीं है।\nIt passes through Gujarat, Rajasthan, MP, Chhattisgarh, Jharkhand, West Bengal, Tripura and Mizoram - not Odisha.", "s": "GS", "lv": "Moderate", "src": "NCERT textbooks (Science/Geography/History, Classes VI-XII) - Class IX Geography, India: Size and Location", "cls": "New - PYQ pattern"}, {"q": "कौन-सी नदी भ्रंश घाटी (Rift valley) से होकर बहती हुई अरब सागर में गिरती है?\nWhich river flows through a rift valley and drains into the Arabian Sea?", "o": ["नर्मदा / Narmada", "गोदावरी / Godavari", "कृष्णा / Krishna", "महानदी / Mahanadi"], "a": 0, "e": "नर्मदा (और तापी) भ्रंश घाटी में पश्चिम की ओर बहकर एस्चुअरी बनाती हैं; गोदावरी, कृष्णा, महानदी बंगाल की खाड़ी में डेल्टा बनाती हैं।\nNarmada (and Tapi) flow west through rift valleys forming estuaries; Godavari, Krishna, Mahanadi form deltas in the Bay of Bengal.", "s": "GS", "lv": "Moderate", "src": "NCERT textbooks (Science/Geography/History, Classes VI-XII) - Class IX Geography, Drainage", "cls": "New - PYQ pattern"}, {"q": "नीति आयोग ने किस संस्था का स्थान लिया?\nNITI Aayog replaced which body?", "o": ["वित्त आयोग / Finance Commission", "राष्ट्रीय विकास परिषद / National Development Council", "अंतर-राज्य परिषद / Inter-State Council", "योजना आयोग / Planning Commission"], "a": 3, "e": "1 जनवरी 2015 को योजना आयोग के स्थान पर नीति आयोग बना; प्रधानमंत्री इसके अध्यक्ष हैं।\nNITI Aayog replaced the Planning Commission on 1 Jan 2015; the PM is its chairperson.", "s": "GS", "lv": "Easy", "src": "NITI Aayog (niti.gov.in) - About us", "cls": "New - PYQ pattern"}, {"q": "भारत में रेपो दर (Repo rate) कौन तय करता है?\nWho decides the repo rate in India?", "o": ["वित्त मंत्रालय / Ministry of Finance", "SEBI / SEBI", "RBI की मौद्रिक नीति समिति / Monetary Policy Committee of RBI", "नाबार्ड / NABARD"], "a": 2, "e": "RBI अधिनियम (धारा 45ZB) के तहत 6 सदस्यीय मौद्रिक नीति समिति (MPC) नीतिगत रेपो दर तय करती है।\nUnder Section 45ZB of the RBI Act, the six-member Monetary Policy Committee fixes the policy repo rate.", "s": "GS", "lv": "Moderate", "src": "Reserve Bank of India (rbi.org.in) - Monetary Policy", "cls": "New - PYQ pattern"}, {"q": "भारत में वस्तु एवं सेवा कर (GST) कब लागू हुआ?\nWhen was the Goods and Services Tax (GST) implemented in India?", "o": ["1 जुलाई 2017 / 1 July 2017", "1 अप्रैल 2016 / 1 April 2016", "1 जनवरी 2018 / 1 January 2018", "1 अप्रैल 2017 / 1 April 2017"], "a": 0, "e": "101वें संविधान संशोधन (2016) के बाद GST 1 जुलाई 2017 से लागू हुआ।\nAfter the 101st Constitutional Amendment (2016), GST came into force on 1 July 2017.", "s": "GS", "lv": "Easy", "src": "GST Council (gstcouncil.gov.in)", "cls": "New - PYQ pattern"}, {"q": "कथकली किस राज्य का शास्त्रीय नृत्य है?\nKathakali is a classical dance of which state?", "o": ["तमिलनाडु / Tamil Nadu", "ओडिशा / Odisha", "आंध्र प्रदेश / Andhra Pradesh", "केरल / Kerala"], "a": 3, "e": "कथकली = केरल; भरतनाट्यम = तमिलनाडु; ओडिसी = ओडिशा; कुचिपुड़ी = आंध्र प्रदेश।\nKathakali - Kerala; Bharatanatyam - Tamil Nadu; Odissi - Odisha; Kuchipudi - Andhra Pradesh.", "s": "GS", "lv": "Easy", "src": "Ministry of Culture / Sangeet Natak Akademi (sangeetnatak.gov.in)", "cls": "New - PYQ pattern"}, {"q": "'हॉर्नबिल उत्सव' (Hornbill Festival) किस राज्य में मनाया जाता है?\nThe Hornbill Festival is celebrated in", "o": ["नागालैंड / Nagaland", "असम / Assam", "मणिपुर / Manipur", "सिक्किम / Sikkim"], "a": 0, "e": "हॉर्नबिल उत्सव हर वर्ष 1-10 दिसंबर को नागालैंड (किसामा, कोहिमा) में होता है।\nThe Hornbill Festival is held every year, 1-10 December, at Kisama near Kohima, Nagaland.", "s": "GS", "lv": "Easy", "src": "Nagaland Tourism (tourismnagaland.com)", "cls": "New - PYQ pattern"}, {"q": "'सकल राष्ट्रीय प्रसन्नता' (Gross National Happiness) की अवधारणा किस पड़ोसी देश से जुड़ी है?\nThe concept of 'Gross National Happiness' is associated with which neighbouring country?", "o": ["नेपाल / Nepal", "श्रीलंका / Sri Lanka", "भूटान / Bhutan", "म्यांमार / Myanmar"], "a": 2, "e": "भूटान के चौथे राजा जिग्मे सिंग्ये वांगचुक ने GDP के स्थान पर GNH की अवधारणा दी।\nBhutan's fourth King Jigme Singye Wangchuck proposed GNH as a measure of progress instead of GDP.", "s": "GS", "lv": "Easy", "src": "Centre for Bhutan & GNH Studies (bhutanstudies.org.bt)", "cls": "New - PYQ pattern"}, {"q": "Read the passage and answer the question.\n\n\"Healthy soil is a living system. A handful of fertile soil holds more organisms than there are people on Earth, and these organisms recycle nutrients, build structure and store carbon. When farmers burn crop residue or apply only chemical fertilisers year after year, this hidden workforce declines. The soil becomes compact, water runs off instead of soaking in, and yields begin to stagnate even though input costs keep rising. Returning organic matter, rotating crops with legumes and testing soil before applying fertiliser can reverse the decline. Such practices may not show dramatic results in a single season, but over a few years they restore the soil's capacity to feed crops and to withstand drought.\"\n\nWhat is the main idea of the passage?", "o": ["Soil is a living system whose health can be restored by good practices", "Chemical fertilisers are always harmful", "Crop residue should be burnt to save time", "Legumes are the only crops farmers should grow"], "a": 0, "e": "The passage describes soil as living and explains how residue return, legume rotation and soil testing restore its health.", "s": "ENG", "lv": "Easy", "src": "Original passage/item by Agrikranti; grammar per Wren & Martin, High School English Grammar and Composition", "cls": "New - PYQ pattern"}, {"q": "Read the passage and answer the question.\n\n\"Healthy soil is a living system. A handful of fertile soil holds more organisms than there are people on Earth, and these organisms recycle nutrients, build structure and store carbon. When farmers burn crop residue or apply only chemical fertilisers year after year, this hidden workforce declines. The soil becomes compact, water runs off instead of soaking in, and yields begin to stagnate even though input costs keep rising. Returning organic matter, rotating crops with legumes and testing soil before applying fertiliser can reverse the decline. Such practices may not show dramatic results in a single season, but over a few years they restore the soil's capacity to feed crops and to withstand drought.\"\n\nThe phrase 'hidden workforce' in the passage refers to", "o": ["farm labourers", "soil organisms", "fertiliser dealers", "earthworms only"], "a": 1, "e": "The 'hidden workforce' is the organisms in soil that recycle nutrients, build structure and store carbon.", "s": "ENG", "lv": "Moderate", "src": "Original passage/item by Agrikranti; grammar per Wren & Martin, High School English Grammar and Composition", "cls": "New - PYQ pattern"}, {"q": "Read the passage and answer the question.\n\n\"Healthy soil is a living system. A handful of fertile soil holds more organisms than there are people on Earth, and these organisms recycle nutrients, build structure and store carbon. When farmers burn crop residue or apply only chemical fertilisers year after year, this hidden workforce declines. The soil becomes compact, water runs off instead of soaking in, and yields begin to stagnate even though input costs keep rising. Returning organic matter, rotating crops with legumes and testing soil before applying fertiliser can reverse the decline. Such practices may not show dramatic results in a single season, but over a few years they restore the soil's capacity to feed crops and to withstand drought.\"\n\nAccording to the passage, what happens when soil becomes compact?", "o": ["Water soaks in faster", "Water runs off instead of soaking in", "Input costs fall", "Organisms increase"], "a": 1, "e": "The passage states that compact soil makes water run off instead of soaking in.", "s": "ENG", "lv": "Moderate", "src": "Original passage/item by Agrikranti; grammar per Wren & Martin, High School English Grammar and Composition", "cls": "New - PYQ pattern"}, {"q": "Read the passage and answer the question.\n\n\"Healthy soil is a living system. A handful of fertile soil holds more organisms than there are people on Earth, and these organisms recycle nutrients, build structure and store carbon. When farmers burn crop residue or apply only chemical fertilisers year after year, this hidden workforce declines. The soil becomes compact, water runs off instead of soaking in, and yields begin to stagnate even though input costs keep rising. Returning organic matter, rotating crops with legumes and testing soil before applying fertiliser can reverse the decline. Such practices may not show dramatic results in a single season, but over a few years they restore the soil's capacity to feed crops and to withstand drought.\"\n\nWhich of the following can be inferred from the passage?", "o": ["Good soil practices give quick results in one season", "Soil testing increases fertiliser use", "Benefits of soil-restoring practices appear gradually over years", "Drought cannot affect healthy soil"], "a": 2, "e": "The last sentence says results may not be dramatic in one season but appear over a few years.", "s": "ENG", "lv": "Moderate", "src": "Original passage/item by Agrikranti; grammar per Wren & Martin, High School English Grammar and Composition", "cls": "New - PYQ pattern"}, {"q": "Read the passage and answer the question.\n\n\"Healthy soil is a living system. A handful of fertile soil holds more organisms than there are people on Earth, and these organisms recycle nutrients, build structure and store carbon. When farmers burn crop residue or apply only chemical fertilisers year after year, this hidden workforce declines. The soil becomes compact, water runs off instead of soaking in, and yields begin to stagnate even though input costs keep rising. Returning organic matter, rotating crops with legumes and testing soil before applying fertiliser can reverse the decline. Such practices may not show dramatic results in a single season, but over a few years they restore the soil's capacity to feed crops and to withstand drought.\"\n\nThe word 'stagnate' in the passage is closest in meaning to", "o": ["increase rapidly", "become polluted", "stop growing", "fluctuate"], "a": 2, "e": "To stagnate means to stop developing or growing.", "s": "ENG", "lv": "Easy", "src": "Original passage/item by Agrikranti; grammar per Wren & Martin, High School English Grammar and Composition", "cls": "New - PYQ pattern"}, {"q": "Find the part of the sentence that has an error.\n(A) Each of the students / (B) have submitted / (C) the assignment / (D) on time.", "o": ["(A)", "(B)", "(C)", "(D)"], "a": 1, "e": "'Each of' takes a singular verb: 'Each of the students has submitted'.", "s": "ENG", "lv": "Easy", "src": "Original passage/item by Agrikranti; grammar per Wren & Martin, High School English Grammar and Composition", "cls": "New - PYQ pattern"}, {"q": "Find the part of the sentence that has an error.\n(A) He is one of the best farmer / (B) who have adopted / (C) drip irrigation / (D) in the district.", "o": ["(B)", "(A)", "(C)", "(D)"], "a": 1, "e": "'One of the best' is followed by a plural noun: 'one of the best farmers'. ('who have' agrees with the plural 'farmers'.)", "s": "ENG", "lv": "Moderate", "src": "Original passage/item by Agrikranti; grammar per Wren & Martin, High School English Grammar and Composition", "cls": "New - PYQ pattern"}, {"q": "Find the part of the sentence that has an error.\n(A) Neither the manager / (B) nor his assistants / (C) was present / (D) at the meeting.", "o": ["(A)", "(B)", "(C)", "(D)"], "a": 2, "e": "With 'neither...nor', the verb agrees with the nearer subject 'assistants' (plural): 'were present'.", "s": "ENG", "lv": "Moderate", "src": "Original passage/item by Agrikranti; grammar per Wren & Martin, High School English Grammar and Composition", "cls": "New - PYQ pattern"}, {"q": "Choose the best replacement for the underlined part: 'If I was the Director, I would start a new farm.' (underlined: 'If I was')", "o": ["If I am", "If I had been", "No improvement", "If I were"], "a": 3, "e": "Hypothetical (unreal) conditions take the subjunctive 'were': 'If I were the Director...'.", "s": "ENG", "lv": "Easy", "src": "Original passage/item by Agrikranti; grammar per Wren & Martin, High School English Grammar and Composition", "cls": "New - PYQ pattern"}, {"q": "Choose the best replacement for the underlined part: 'Hardly had he reached the field than it started raining.' (underlined: 'than')", "o": ["when", "then", "that", "No improvement"], "a": 0, "e": "'Hardly/Scarcely ... when' is the correct pair; 'No sooner ... than'.", "s": "ENG", "lv": "Moderate", "src": "Original passage/item by Agrikranti; grammar per Wren & Martin, High School English Grammar and Composition", "cls": "New - PYQ pattern"}, {"q": "Choose the best replacement for the underlined part: 'The scientist is working on this project since 2022.' (underlined: 'is working')", "o": ["has been working", "was working", "had worked", "No improvement"], "a": 0, "e": "An action begun in the past and still continuing, with 'since', takes the present perfect continuous.", "s": "ENG", "lv": "Moderate", "src": "Original passage/item by Agrikranti; grammar per Wren & Martin, High School English Grammar and Composition", "cls": "New - PYQ pattern"}, {"q": "Fill in the blank: The farmers were advised to refrain ______ burning paddy straw.", "o": ["to", "from", "of", "against"], "a": 1, "e": "'Refrain' is always followed by 'from'.", "s": "ENG", "lv": "Easy", "src": "Original passage/item by Agrikranti; grammar per Wren & Martin, High School English Grammar and Composition", "cls": "New - PYQ pattern"}, {"q": "Fill in the blank: Mathematics ______ my favourite subject at school.", "o": ["are", "were", "have", "is"], "a": 3, "e": "Subjects ending in -ics (mathematics, physics, economics) take a singular verb when used as the name of a subject.", "s": "ENG", "lv": "Easy", "src": "Original passage/item by Agrikranti; grammar per Wren & Martin, High School English Grammar and Composition", "cls": "New - PYQ pattern"}, {"q": "Fill in the blank: The yield would have been higher if the crop ______ irrigated at the critical stage.", "o": ["was", "had been", "has been", "would be"], "a": 1, "e": "Third conditional: 'would have + past participle' pairs with 'if + past perfect' (had been).", "s": "ENG", "lv": "Moderate", "src": "Original passage/item by Agrikranti; grammar per Wren & Martin, High School English Grammar and Composition", "cls": "New - PYQ pattern"}, {"q": "Choose the word most similar in meaning to 'ABUNDANT'.", "o": ["Scarce", "Rare", "Plentiful", "Tiny"], "a": 2, "e": "Abundant means existing in large quantities - plentiful.", "s": "ENG", "lv": "Easy", "src": "Oxford Learner's Dictionary (oxfordlearnersdictionaries.com)", "cls": "New - PYQ pattern"}, {"q": "Choose the word most similar in meaning to 'METICULOUS'.", "o": ["Careless", "Quick", "Very careful and precise", "Generous"], "a": 2, "e": "Meticulous means showing great attention to detail.", "s": "ENG", "lv": "Moderate", "src": "Oxford Learner's Dictionary (oxfordlearnersdictionaries.com)", "cls": "New - PYQ pattern"}, {"q": "Choose the word opposite in meaning to 'FERTILE'.", "o": ["Productive", "Rich", "Barren", "Fruitful"], "a": 2, "e": "Fertile (able to produce) is opposite to barren (unable to produce).", "s": "ENG", "lv": "Easy", "src": "Oxford Learner's Dictionary (oxfordlearnersdictionaries.com)", "cls": "New - PYQ pattern"}, {"q": "Choose the word opposite in meaning to 'TRANSPARENT'.", "o": ["Clear", "Opaque", "Visible", "Obvious"], "a": 1, "e": "Transparent lets light through; opaque does not.", "s": "ENG", "lv": "Moderate", "src": "Oxford Learner's Dictionary (oxfordlearnersdictionaries.com)", "cls": "New - PYQ pattern"}, {"q": "Choose the correct meaning of the idiom: 'To make hay while the sun shines'", "o": ["To work hard in summer", "To make the best use of a favourable opportunity", "To dry crops in sunlight", "To waste time"], "a": 1, "e": "The idiom means to take advantage of a good opportunity while it lasts.", "s": "ENG", "lv": "Moderate", "src": "Oxford Dictionary of Idioms", "cls": "New - PYQ pattern"}, {"q": "Choose the correct meaning of the idiom: 'To bury the hatchet'", "o": ["To end a quarrel and make peace", "To hide weapons", "To start a fight", "To plant a tree"], "a": 0, "e": "To bury the hatchet means to stop quarrelling and become friendly.", "s": "ENG", "lv": "Moderate", "src": "Oxford Dictionary of Idioms", "cls": "New - PYQ pattern"}, {"q": "Choose the one word for: 'A person who studies insects'.", "o": ["Ornithologist", "Entomologist", "Etymologist", "Agronomist"], "a": 1, "e": "Entomologist studies insects; ornithologist - birds; etymologist - origin of words; agronomist - crop production and soil management.", "s": "ENG", "lv": "Easy", "src": "Oxford Learner's Dictionary (oxfordlearnersdictionaries.com)", "cls": "New - PYQ pattern"}, {"q": "Choose the one word for: 'A remedy for all diseases or problems'.", "o": ["Antidote", "Panacea", "Placebo", "Vaccine"], "a": 1, "e": "A panacea is a solution or remedy for all difficulties or diseases.", "s": "ENG", "lv": "Moderate", "src": "Oxford Learner's Dictionary (oxfordlearnersdictionaries.com)", "cls": "New - PYQ pattern"}, {"q": "Change into passive voice: 'The farmers are harvesting the wheat.'", "o": ["The wheat is harvested by the farmers.", "The wheat was being harvested by the farmers.", "The wheat has been harvested by the farmers.", "The wheat is being harvested by the farmers."], "a": 3, "e": "Present continuous active (are harvesting) becomes 'is/are being + past participle' in passive.", "s": "ENG", "lv": "Moderate", "src": "Original passage/item by Agrikranti; grammar per Wren & Martin, High School English Grammar and Composition", "cls": "New - PYQ pattern"}, {"q": "Change into indirect speech: He said, \"I am testing the soil.\"", "o": ["He said that he is testing the soil.", "He said that I was testing the soil.", "He said that he was testing the soil.", "He told that he had tested the soil."], "a": 2, "e": "With a past reporting verb, present continuous changes to past continuous and 'I' becomes 'he'.", "s": "ENG", "lv": "Moderate", "src": "Original passage/item by Agrikranti; grammar per Wren & Martin, High School English Grammar and Composition", "cls": "New - PYQ pattern"}, {"q": "Choose the correctly spelt word.", "o": ["Accommodation", "Accomodation", "Acommodation", "Accommodasion"], "a": 0, "e": "Correct spelling: accommodation (double c, double m).", "s": "ENG", "lv": "Easy", "src": "Oxford Learner's Dictionary (oxfordlearnersdictionaries.com)", "cls": "New - PYQ pattern"}, {"q": "0.25 × 0.4 ÷ 0.05 का मान क्या है?\nFind the value of 0.25 × 0.4 ÷ 0.05.", "o": ["2", "0.2", "20", "0.5"], "a": 0, "e": "0.25 × 0.4 = 0.1; 0.1 ÷ 0.05 = 2।\n0.25 × 0.4 = 0.1; 0.1 ÷ 0.05 = 2.", "s": "QA", "lv": "Easy", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "√0.0169 का मान है\nThe value of √0.0169 is", "o": ["0.013", "1.3", "0.0013", "0.13"], "a": 3, "e": "0.0169 = 169/10000, अतः √ = 13/100 = 0.13।\n0.0169 = 169/10000, so the root is 13/100 = 0.13.", "s": "QA", "lv": "Easy", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "500 के 40% का 15% कितना है?\nWhat is 15% of 40% of 500?", "o": ["60", "20", "45", "30"], "a": 3, "e": "500 का 40% = 200; 200 का 15% = 30।\n40% of 500 = 200; 15% of 200 = 30.", "s": "QA", "lv": "Easy", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "5 संख्याओं का औसत 24 है। यदि उनमें से 40 को हटा दें, तो शेष 4 संख्याओं का औसत क्या होगा?\nThe average of 5 numbers is 24. If the number 40 is removed, what is the average of the remaining 4 numbers?", "o": ["21", "18", "20", "22"], "a": 2, "e": "योग = 5 × 24 = 120; 120 - 40 = 80; 80 ÷ 4 = 20।\nSum = 120; 120 - 40 = 80; 80/4 = 20.", "s": "QA", "lv": "Easy", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "यदि A : B = 2 : 3 और B : C = 4 : 5 हो, तो A : B : C = ?\nIf A : B = 2 : 3 and B : C = 4 : 5, then A : B : C = ?", "o": ["2 : 3 : 5", "8 : 12 : 15", "8 : 12 : 5", "4 : 6 : 5"], "a": 1, "e": "B को समान करें: A:B = 8:12, B:C = 12:15, अतः 8:12:15।\nMake B common: 8:12 and 12:15, so 8:12:15.", "s": "QA", "lv": "Easy", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "₹8,000 पर 6% वार्षिक दर से 3 वर्ष का साधारण ब्याज कितना होगा?\nFind the simple interest on ₹8,000 at 6% per annum for 3 years.", "o": ["₹1,200", "₹1,440", "₹1,600", "₹1,520"], "a": 1, "e": "SI = P × R × T / 100 = 8000 × 6 × 3 / 100 = ₹1,440।\nSI = 8000 × 6 × 3 / 100 = ₹1,440.", "s": "QA", "lv": "Easy", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "₹10,000 पर 10% वार्षिक चक्रवृद्धि दर से 2 वर्ष का चक्रवृद्धि ब्याज कितना होगा?\nFind the compound interest on ₹10,000 at 10% per annum for 2 years, compounded annually.", "o": ["₹2,000", "₹2,210", "₹2,100", "₹2,010"], "a": 2, "e": "A = 10000 × (1.1)^2 = 12,100; CI = 12,100 - 10,000 = ₹2,100।\nA = 10000 × 1.21 = 12,100; CI = ₹2,100.", "s": "QA", "lv": "Moderate", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "एक वस्तु ₹400 में खरीदकर ₹460 में बेची गई। लाभ प्रतिशत क्या है?\nAn article bought for ₹400 is sold for ₹460. Find the profit per cent.", "o": ["12%", "15%", "16%", "13.5%"], "a": 1, "e": "लाभ = 60; 60/400 × 100 = 15%।\nProfit = 60; 60/400 × 100 = 15%.", "s": "QA", "lv": "Easy", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "₹1,200 अंकित मूल्य वाली वस्तु पर 10% और 5% की क्रमिक छूट के बाद विक्रय मूल्य क्या होगा?\nAn article marked at ₹1,200 is sold after successive discounts of 10% and 5%. Find the selling price.", "o": ["₹1,020", "₹1,026", "₹1,050", "₹1,080"], "a": 1, "e": "1200 × 0.90 = 1080; 1080 × 0.95 = ₹1,026।\n1200 × 0.90 = 1080; 1080 × 0.95 = ₹1,026.", "s": "QA", "lv": "Moderate", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "A ने ₹6,000 12 महीने के लिए और B ने ₹8,000 6 महीने के लिए निवेश किया। ₹3,000 के लाभ में A का हिस्सा कितना है?\nA invests ₹6,000 for 12 months and B invests ₹8,000 for 6 months. Find A's share in a profit of ₹3,000.", "o": ["₹1,200", "₹1,500", "₹2,000", "₹1,800"], "a": 3, "e": "अनुपात = 6000×12 : 8000×6 = 72000 : 48000 = 3 : 2; A = 3000 × 3/5 = ₹1,800।\nRatio 72000 : 48000 = 3 : 2; A's share = 3000 × 3/5 = ₹1,800.", "s": "QA", "lv": "Moderate", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "₹30/kg और ₹45/kg वाले चावल को किस अनुपात में मिलाएँ कि मिश्रण का मूल्य ₹36/kg हो?\nIn what ratio must rice at ₹30/kg be mixed with rice at ₹45/kg to get a mixture worth ₹36/kg?", "o": ["2 : 3", "1 : 2", "3 : 1", "3 : 2"], "a": 3, "e": "एलिगेशन: (45 - 36) : (36 - 30) = 9 : 6 = 3 : 2।\nAlligation: (45 - 36) : (36 - 30) = 9 : 6 = 3 : 2.", "s": "QA", "lv": "Moderate", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "150 m लंबी रेलगाड़ी 54 km/h की चाल से एक खंभे को कितने समय में पार करेगी?\nA 150 m long train running at 54 km/h crosses a pole in", "o": ["10 सेकंड / 10 s", "9 सेकंड / 9 s", "15 सेकंड / 15 s", "12 सेकंड / 12 s"], "a": 0, "e": "54 km/h = 54 × 5/18 = 15 m/s; समय = 150/15 = 10 s।\n54 km/h = 15 m/s; time = 150/15 = 10 s.", "s": "QA", "lv": "Easy", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "A किसी कार्य को 12 दिन में और B 18 दिन में कर सकता है। दोनों मिलकर कितने दिन में करेंगे?\nA can finish a work in 12 days and B in 18 days. In how many days will they finish it together?", "o": ["7.5 दिन / 7.5 days", "7.2 दिन / 7.2 days", "6 दिन / 6 days", "8 दिन / 8 days"], "a": 1, "e": "1/12 + 1/18 = 5/36; समय = 36/5 = 7.2 दिन।\n1/12 + 1/18 = 5/36; time = 36/5 = 7.2 days.", "s": "QA", "lv": "Moderate", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "यदि a + b = 10 और ab = 21 हो, तो a² + b² = ?\nIf a + b = 10 and ab = 21, then a² + b² = ?", "o": ["79", "42", "58", "62"], "a": 2, "e": "a² + b² = (a + b)² - 2ab = 100 - 42 = 58।\na² + b² = (a + b)² - 2ab = 100 - 42 = 58.", "s": "QA", "lv": "Moderate", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "1/(√3 - √2) का परिमेयीकृत (rationalised) रूप है\nThe rationalised form of 1/(√3 - √2) is", "o": ["√3 - √2", "(√3 + √2)/5", "√3 + √2", "1/(√3 + √2)"], "a": 2, "e": "अंश-हर को (√3 + √2) से गुणा करें: हर = 3 - 2 = 1, अतः √3 + √2।\nMultiply by (√3 + √2): denominator = 3 - 2 = 1, giving √3 + √2.", "s": "QA", "lv": "Moderate", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "रेखा 2x + 3y = 12 x-अक्ष को किस बिंदु पर काटती है?\nThe line 2x + 3y = 12 cuts the x-axis at", "o": ["(0, 4)", "(4, 0)", "(6, 0)", "(0, 6)"], "a": 2, "e": "x-अक्ष पर y = 0, अतः 2x = 12, x = 6; बिंदु (6, 0)।\nOn the x-axis y = 0, so x = 6; point (6, 0).", "s": "QA", "lv": "Easy", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "त्रिभुज का केंद्रक (Centroid) प्रत्येक माध्यिका को शीर्ष से किस अनुपात में विभाजित करता है?\nThe centroid of a triangle divides each median, from the vertex, in the ratio", "o": ["1 : 1", "1 : 2", "3 : 1", "2 : 1"], "a": 3, "e": "केंद्रक माध्यिका को शीर्ष से 2 : 1 में बाँटता है।\nThe centroid divides each median in the ratio 2 : 1 from the vertex.", "s": "QA", "lv": "Easy", "src": "NCERT Mathematics, Class IX-X (Triangles; Coordinate Geometry)", "cls": "New - PYQ pattern"}, {"q": "एक बिंदु वृत्त के केंद्र से 13 cm दूर है और वृत्त की त्रिज्या 5 cm है। उस बिंदु से खींची गई स्पर्शरेखा की लंबाई क्या है?\nA point is 13 cm from the centre of a circle of radius 5 cm. Find the length of the tangent from the point.", "o": ["8 cm", "10 cm", "18 cm", "12 cm"], "a": 3, "e": "स्पर्शरेखा त्रिज्या पर लंब होती है: √(13² - 5²) = √144 = 12 cm।\nTangent ⟂ radius: √(169 - 25) = 12 cm.", "s": "QA", "lv": "Moderate", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "एक सम षट्भुज (Regular hexagon) के प्रत्येक आंतरिक कोण का माप है\nEach interior angle of a regular hexagon measures", "o": ["120°", "108°", "135°", "144°"], "a": 0, "e": "आंतरिक कोण = (n - 2) × 180/n = 4 × 180/6 = 120°।\nInterior angle = (n - 2) × 180/n = 120°.", "s": "QA", "lv": "Easy", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "त्रिज्या 7 cm और ऊँचाई 10 cm वाले बेलन का आयतन क्या है? (π = 22/7)\nFind the volume of a cylinder of radius 7 cm and height 10 cm. (π = 22/7)", "o": ["1,440 cm³", "770 cm³", "1,540 cm³", "2,200 cm³"], "a": 2, "e": "V = πr²h = 22/7 × 49 × 10 = 1,540 cm³।\nV = πr²h = 22/7 × 49 × 10 = 1,540 cm³.", "s": "QA", "lv": "Easy", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "7 cm त्रिज्या वाले गोले का पृष्ठीय क्षेत्रफल है (π = 22/7)\nThe surface area of a sphere of radius 7 cm is (π = 22/7)", "o": ["1,437 cm²", "308 cm²", "616 cm²", "154 cm²"], "a": 2, "e": "S = 4πr² = 4 × 22/7 × 49 = 616 cm²।\nS = 4πr² = 616 cm².", "s": "QA", "lv": "Easy", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "त्रिज्या 3 cm और ऊँचाई 4 cm वाले शंकु का वक्र पृष्ठीय क्षेत्रफल है\nThe curved surface area of a cone of radius 3 cm and height 4 cm is", "o": ["12π cm²", "24π cm²", "20π cm²", "15π cm²"], "a": 3, "e": "तिर्यक ऊँचाई l = √(3² + 4²) = 5; CSA = πrl = π × 3 × 5 = 15π cm²।\nSlant height l = 5; CSA = πrl = 15π cm².", "s": "QA", "lv": "Moderate", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "यदि tan θ = 3/4 (θ न्यूनकोण) हो, तो sin θ = ?\nIf tan θ = 3/4 (θ acute), then sin θ = ?", "o": ["4/5", "3/4", "3/5", "5/3"], "a": 2, "e": "लंब = 3, आधार = 4, कर्ण = 5; sin θ = 3/5।\nPerpendicular 3, base 4, hypotenuse 5; sin θ = 3/5.", "s": "QA", "lv": "Easy", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "एक मीनार के पाद से 30 m दूर स्थित बिंदु से उसके शिखर का उन्नयन कोण 60° है। मीनार की ऊँचाई क्या है?\nFrom a point 30 m from the foot of a tower, the angle of elevation of its top is 60°. Find the height of the tower.", "o": ["10√3 m", "30√3 m", "30 m", "60 m"], "a": 1, "e": "tan 60° = h/30, अतः h = 30√3 m।\ntan 60° = h/30, so h = 30√3 m.", "s": "QA", "lv": "Moderate", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "एक किसान के ₹50,000 के कुल व्यय को पाई चार्ट में दिखाया गया है। उर्वरक का भाग 72° है। उर्वरक पर कितना व्यय हुआ?\nA farmer's total expenditure of ₹50,000 is shown in a pie chart. The fertiliser sector is 72°. How much was spent on fertiliser?", "o": ["₹10,000", "₹7,200", "₹12,000", "₹14,400"], "a": 0, "e": "व्यय = 72/360 × 50,000 = ₹10,000।\nAmount = 72/360 × 50,000 = ₹10,000.", "s": "QA", "lv": "Moderate", "src": "Standard arithmetic; answer recomputed in code (Agrikranti check)", "cls": "New - PYQ pattern"}, {"q": "निम्नलिखित में से कौन-सी रबी फसल है?\nWhich of the following is a rabi crop?", "o": ["धान / Rice", "गेहूँ / Wheat", "मक्का / Maize", "कपास / Cotton"], "a": 1, "e": "रबी फसलें अक्टूबर-नवंबर में बोई जाती हैं (गेहूँ, चना, सरसों); धान, मक्का, कपास खरीफ फसलें हैं।\nRabi crops are sown in Oct-Nov (wheat, gram, mustard); rice, maize and cotton are kharif crops.", "s": "GAG", "lv": "Easy", "src": "ICAR Handbook of Agriculture (ICAR-DKMA, New Delhi) - Crop seasons", "cls": "New - PYQ pattern"}, {"q": "हवा की गति मापने वाला यंत्र है\nThe instrument used to measure wind speed is", "o": ["हाइग्रोमीटर / Hygrometer", "बैरोमीटर / Barometer", "एनीमोमीटर / Anemometer", "लाइसीमीटर / Lysimeter"], "a": 2, "e": "एनीमोमीटर = हवा की गति; हाइग्रोमीटर = आर्द्रता; बैरोमीटर = वायुदाब; लाइसीमीटर = वाष्पोत्सर्जन (ET)।\nAnemometer - wind speed; hygrometer - humidity; barometer - pressure; lysimeter - evapotranspiration.", "s": "GAG", "lv": "Easy", "src": "IMD agromet observatory manual (imd.gov.in); Mavi & Tupper, Agrometeorology", "cls": "New - PYQ pattern"}, {"q": "मृदा परीक्षण प्रयोगशालाओं में उपलब्ध नाइट्रोजन ज्ञात करने की सामान्य विधि है\nAvailable nitrogen in soil testing laboratories is commonly estimated by", "o": ["क्षारीय KMnO4 विधि (सुब्बैया व असीजा) / Alkaline KMnO4 method (Subbiah & Asija)", "ओल्सेन विधि / Olsen's method", "वॉकली-ब्लैक विधि / Walkley-Black method", "ब्रे विधि / Bray's method"], "a": 0, "e": "उपलब्ध N = क्षारीय परमैंगनेट विधि (Subbiah & Asija, 1956); उपलब्ध P = Olsen/Bray; जैविक कार्बन = Walkley-Black।\nAvailable N - alkaline permanganate (Subbiah & Asija, 1956); available P - Olsen/Bray; organic carbon - Walkley-Black.", "s": "GAG", "lv": "Moderate", "src": "Subbiah & Asija (1956), Current Science 25: 259-260; DAC&FW, Methods Manual: Soil Testing in India (2011)", "cls": "New - PYQ pattern"}, {"q": "अरहर (Pigeonpea) का वानस्पतिक नाम है\nThe botanical name of pigeonpea is", "o": ["Cicer arietinum", "Cajanus cajan", "Vigna radiata", "Lens culinaris"], "a": 1, "e": "अरहर = Cajanus cajan; चना = Cicer arietinum; मूंग = Vigna radiata; मसूर = Lens culinaris।\nPigeonpea - Cajanus cajan; chickpea - Cicer arietinum; mungbean - Vigna radiata; lentil - Lens culinaris.", "s": "GAG", "lv": "Easy", "src": "ICAR Handbook of Agriculture (ICAR-DKMA, New Delhi) - Pulses", "cls": "New - PYQ pattern"}, {"q": "'शुद्ध वंशक्रम सिद्धांत' (Pure line theory) किसने दिया?\nWho proposed the pure line theory?", "o": ["मेंडल / Mendel", "शल / Shull", "वाविलोव / Vavilov", "जोहानसन / Johannsen"], "a": 3, "e": "डब्ल्यू. जोहानसन (1903) ने सेम (Phaseolus vulgaris) के बीज भार पर शुद्ध वंशक्रम सिद्धांत दिया।\nW. Johannsen (1903) proposed the pure line theory working on seed weight of Phaseolus vulgaris.", "s": "GAG", "lv": "Moderate", "src": "B.D. Singh, Plant Breeding: Principles and Methods (Kalyani Publishers)", "cls": "New - PYQ pattern"}, {"q": "पादप कोशिका की 'पूर्णशक्तता' (Totipotency) की अवधारणा किसने दी?\nThe concept of cellular totipotency of plant cells was given by", "o": ["हैबरलैंट / Haberlandt", "मुराशिगे व स्कूग / Murashige and Skoog", "व्हाइट / White", "स्टीवर्ड / Steward"], "a": 0, "e": "हैबरलैंट (1902) ने पूर्णशक्तता की परिकल्पना दी; Murashige & Skoog (1962) ने MS माध्यम दिया; स्टीवर्ड ने गाजर से कायिक भ्रूणजनन दिखाया।\nHaberlandt (1902) proposed totipotency; Murashige & Skoog (1962) gave MS medium; Steward showed somatic embryogenesis in carrot.", "s": "GAG", "lv": "Moderate", "src": "H.S. Chawla, Introduction to Plant Biotechnology (Oxford & IBH)", "cls": "New - PYQ pattern"}, {"q": "धान के झोंका रोग (Blast) का रोगकारक है\nThe causal organism of rice blast is", "o": ["Xanthomonas oryzae pv. oryzae", "Rhizoctonia solani", "Magnaporthe oryzae (Pyricularia oryzae)", "Ustilaginoidea virens"], "a": 2, "e": "ब्लास्ट = Magnaporthe oryzae (अलैंगिक अवस्था Pyricularia oryzae); BLB = Xanthomonas; शीथ ब्लाइट = Rhizoctonia; आभासी कंड = Ustilaginoidea।\nBlast - Magnaporthe oryzae; BLB - Xanthomonas; sheath blight - Rhizoctonia; false smut - Ustilaginoidea.", "s": "GAG", "lv": "Easy", "src": "R.S. Singh, Plant Diseases (Oxford & IBH)", "cls": "New - PYQ pattern"}, {"q": "गन्ने का लाल सड़न (Red rot) रोग किसके कारण होता है?\nRed rot of sugarcane is caused by", "o": ["Colletotrichum falcatum", "Ustilago scitaminea", "Fusarium moniliforme", "Puccinia erianthi"], "a": 0, "e": "लाल सड़न = Colletotrichum falcatum (\"गन्ने का कैंसर\"); कंड (smut) = Ustilago scitaminea।\nRed rot - Colletotrichum falcatum; smut - Ustilago (Sporisorium) scitaminea.", "s": "GAG", "lv": "Easy", "src": "R.S. Singh, Plant Diseases (Oxford & IBH); ICAR-IISR, Lucknow", "cls": "New - PYQ pattern"}, {"q": "चावल-गेहूँ फसल प्रणाली में गेहूँ का प्रमुख खरपतवार 'गुल्ली डंडा' का वैज्ञानिक नाम है\nThe major weed of wheat in the rice-wheat system, 'gulli danda', is", "o": ["Avena ludoviciana", "Phalaris minor", "Chenopodium album", "Echinochloa crus-galli"], "a": 1, "e": "गुल्ली डंडा = Phalaris minor (isoproturon प्रतिरोध के लिए प्रसिद्ध); जंगली जई = Avena; बथुआ = Chenopodium; सांवा = Echinochloa (धान का खरपतवार)।\nGulli danda - Phalaris minor; wild oat - Avena; bathua - Chenopodium; barnyard grass - Echinochloa (rice weed).", "s": "GAG", "lv": "Moderate", "src": "ICAR-DWR, Jabalpur; Rao, Principles of Weed Science", "cls": "New - PYQ pattern"}, {"q": "'मुर्रा' (Murrah) किस पशु की नस्ल है?\n'Murrah' is a breed of", "o": ["भैंस / Buffalo", "गाय / Cow", "बकरी / Goat", "भेड़ / Sheep"], "a": 0, "e": "मुर्रा भैंस की सर्वश्रेष्ठ दुधारू नस्ल है (हरियाणा)।\nMurrah is the best dairy buffalo breed, from Haryana.", "s": "GAG", "lv": "Easy", "src": "ICAR-NBAGR, Breed registration list (nbagr.icar.gov.in)", "cls": "New - PYQ pattern"}, {"q": "गाय का औसत गर्भकाल (Gestation period) लगभग कितना होता है?\nThe average gestation period of a cow is about", "o": ["150 दिन / 150 days", "210 दिन / 210 days", "280 दिन / 280 days", "310 दिन / 310 days"], "a": 2, "e": "गाय लगभग 280-285 दिन; भैंस लगभग 310 दिन; बकरी लगभग 150 दिन।\nCow about 280-285 days; buffalo about 310 days; goat about 150 days.", "s": "GAG", "lv": "Moderate", "src": "ICAR Handbook of Animal Husbandry (ICAR-DKMA)", "cls": "New - PYQ pattern"}, {"q": "'रॉक बी' (Rock bee) किस मधुमक्खी को कहा जाता है?\nWhich honey bee is called the 'rock bee'?", "o": ["Apis cerana", "Apis mellifera", "Apis florea", "Apis dorsata"], "a": 3, "e": "Apis dorsata = रॉक बी (सबसे बड़ी, खुले में एकल छत्ता); A. florea = लघु मधुमक्खी; A. cerana = भारतीय; A. mellifera = इटैलियन।\nApis dorsata - rock bee; A. florea - little bee; A. cerana - Indian bee; A. mellifera - Italian bee.", "s": "GAG", "lv": "Moderate", "src": "ICAR Handbook of Agriculture - Apiculture; NBB (nbb.gov.in)", "cls": "New - PYQ pattern"}, {"q": "निम्नलिखित में से कौन भारतीय मुख्य कार्प (Indian Major Carp) नहीं है?\nWhich of the following is NOT an Indian major carp?", "o": ["कतला / Catla", "रोहू / Rohu", "ग्रास कार्प / Grass carp", "मृगल / Mrigal"], "a": 2, "e": "भारतीय मुख्य कार्प: कतला, रोहू, मृगल (कालबासु भी)। ग्रास कार्प (Ctenopharyngodon idella) विदेशी कार्प है।\nIndian major carps: catla, rohu, mrigal (also calbasu). Grass carp is an exotic carp.", "s": "GAG", "lv": "Easy", "src": "ICAR Handbook of Fisheries and Aquaculture (ICAR-DKMA)", "cls": "New - PYQ pattern"}, {"q": "निम्नलिखित में से कौन प्राथमिक जुताई (Primary tillage) का यंत्र है?\nWhich of the following is a primary tillage implement?", "o": ["मोल्डबोर्ड हल / Mouldboard plough", "कल्टीवेटर / Cultivator", "डिस्क हैरो / Disc harrow", "रोलर / Roller"], "a": 0, "e": "मोल्डबोर्ड हल मिट्टी को काटकर पलटता है (प्राथमिक जुताई); कल्टीवेटर, हैरो, रोलर द्वितीयक जुताई यंत्र हैं।\nThe mouldboard plough cuts and inverts soil (primary tillage); cultivator, harrow and roller are secondary tillage implements.", "s": "GAG", "lv": "Easy", "src": "Michael & Ojha, Principles of Agricultural Engineering Vol. I", "cls": "New - PYQ pattern"}, {"q": "किसान कॉल सेंटर (Kisan Call Centre) का टोल-फ्री नंबर है\nThe toll-free number of the Kisan Call Centre is", "o": ["1800-180-1551", "1800-11-0001", "155261", "1800-425-1556"], "a": 0, "e": "किसान कॉल सेंटर (2004 से) का नंबर 1800-180-1551 है; किसान स्थानीय भाषा में विशेषज्ञ सलाह लेते हैं।\nKisan Call Centres (since 2004) use 1800-180-1551 for advice in local languages.", "s": "GAG", "lv": "Easy", "src": "Department of Agriculture & Farmers Welfare (agriwelfare.gov.in) - Kisan Call Centre", "cls": "New - PYQ pattern"}, {"q": "भारत में फसलों के न्यूनतम समर्थन मूल्य (MSP) की संस्तुति कौन करता है?\nWho recommends the Minimum Support Prices (MSP) of crops in India?", "o": ["NAFED", "CACP / कृषि लागत एवं मूल्य आयोग", "FCI / भारतीय खाद्य निगम", "नीति आयोग / NITI Aayog"], "a": 1, "e": "CACP (कृषि लागत एवं मूल्य आयोग) संस्तुति करता है; अंतिम निर्णय CCEA लेती है।\nCACP recommends MSP; the Cabinet Committee on Economic Affairs (CCEA) takes the final decision.", "s": "GAG", "lv": "Easy", "src": "CACP (cacp.da.gov.in)", "cls": "New - PYQ pattern"}, {"q": "प्रधानमंत्री फसल बीमा योजना (PMFBY) में खरीफ की खाद्य व तिलहन फसलों के लिए किसान का अधिकतम प्रीमियम कितना है?\nUnder PMFBY, the maximum farmer's premium for kharif food and oilseed crops is", "o": ["1.5% बीमित राशि का / 1.5% of sum insured", "5% बीमित राशि का / 5% of sum insured", "10% बीमित राशि का / 10% of sum insured", "2% बीमित राशि का / 2% of sum insured"], "a": 3, "e": "PMFBY (2016): खरीफ 2%, रबी 1.5%, वार्षिक वाणिज्यिक/बागवानी फसलें 5%।\nPMFBY (2016): kharif 2%, rabi 1.5%, annual commercial/horticultural crops 5%.", "s": "GAG", "lv": "Moderate", "src": "PMFBY operational guidelines (pmfby.gov.in)", "cls": "New - PYQ pattern"}, {"q": "भारतीय कृषि अनुसंधान परिषद (ICAR) की स्थापना किस वर्ष हुई?\nThe Indian Council of Agricultural Research (ICAR) was established in", "o": ["1929", "1905", "1947", "1965"], "a": 0, "e": "रॉयल कमीशन ऑन एग्रीकल्चर की संस्तुति पर 16 जुलाई 1929 को 'इंपीरियल काउंसिल ऑफ एग्रीकल्चरल रिसर्च' के रूप में स्थापना हुई।\nEstablished on 16 July 1929 as the Imperial Council of Agricultural Research, on the recommendation of the Royal Commission on Agriculture.", "s": "GAG", "lv": "Easy", "src": "ICAR (icar.org.in) - About us", "cls": "New - PYQ pattern"}, {"q": "भारत का पहला कृषि विज्ञान केंद्र (KVK) 1974 में कहाँ स्थापित हुआ?\nIndia's first Krishi Vigyan Kendra (KVK) was established in 1974 at", "o": ["पुडुचेरी / Puducherry", "करनाल / Karnal", "पूसा, नई दिल्ली / Pusa, New Delhi", "लुधियाना / Ludhiana"], "a": 0, "e": "मोहन सिंह मेहता समिति (1973) की संस्तुति पर पहला KVK 1974 में पुडुचेरी में (TNAU के अधीन) खुला।\nOn the Mohan Singh Mehta Committee (1973) recommendation, the first KVK started in 1974 at Puducherry under TNAU.", "s": "GAG", "lv": "Moderate", "src": "ICAR, Agricultural Extension Division - KVK (kvk.icar.gov.in)", "cls": "New - PYQ pattern"}, {"q": "पौधा किस्म और कृषक अधिकार संरक्षण (PPV&FR) अधिनियम किस वर्ष पारित हुआ?\nThe Protection of Plant Varieties and Farmers' Rights (PPV&FR) Act was enacted in", "o": ["1966", "2002", "2001", "2005"], "a": 2, "e": "PPV&FR अधिनियम 2001 में बना; प्राधिकरण 2005 में स्थापित हुआ। बीज अधिनियम = 1966, जैव विविधता अधिनियम = 2002।\nPPV&FR Act - 2001; Authority set up in 2005. Seeds Act 1966; Biological Diversity Act 2002.", "s": "GAG", "lv": "Easy", "src": "PPV&FR Authority (plantauthority.gov.in)", "cls": "New - PYQ pattern"}, {"q": "राष्ट्रीय जैव विविधता प्राधिकरण (NBA) का मुख्यालय कहाँ है?\nWhere is the headquarters of the National Biodiversity Authority (NBA)?", "o": ["नई दिल्ली / New Delhi", "हैदराबाद / Hyderabad", "बेंगलुरु / Bengaluru", "चेन्नई / Chennai"], "a": 3, "e": "जैव विविधता अधिनियम 2002 के तहत NBA 2003 में चेन्नई में स्थापित हुआ। अधिनियम में 2023 में संशोधन हुआ।\nThe NBA was set up in 2003 at Chennai under the Biological Diversity Act, 2002 (amended in 2023).", "s": "GAG", "lv": "Moderate", "src": "National Biodiversity Authority (nbaindia.org)", "cls": "New - PYQ pattern"}, {"q": "कीटनाशी अधिनियम, 1968 के अंतर्गत कीटनाशकों का पंजीकरण कौन करता है?\nWhich body registers insecticides under the Insecticides Act, 1968?", "o": ["FSSAI", "केंद्रीय कीटनाशी बोर्ड एवं पंजीकरण समिति (CIB&RC) / Central Insecticides Board & Registration Committee", "भारतीय मानक ब्यूरो (BIS) / Bureau of Indian Standards", "राष्ट्रीय जैव विविधता प्राधिकरण / NBA"], "a": 1, "e": "धारा 9 के तहत पंजीकरण समिति (CIB&RC, फरीदाबाद) कीटनाशकों का पंजीकरण करती है।\nUnder Section 9, the Registration Committee (CIB&RC, Faridabad) registers insecticides.", "s": "GAG", "lv": "Moderate", "src": "Insecticides Act, 1968; DPPQ&S (ppqs.gov.in) - CIB&RC", "cls": "New - PYQ pattern"}, {"q": "CIMMYT (अंतरराष्ट्रीय मक्का एवं गेहूँ सुधार केंद्र) का मुख्यालय किस देश में है?\nCIMMYT (International Maize and Wheat Improvement Center) is headquartered in", "o": ["फिलीपींस / Philippines", "मेक्सिको / Mexico", "नाइजीरिया / Nigeria", "कोलंबिया / Colombia"], "a": 1, "e": "CIMMYT = मेक्सिको (El Batan, Texcoco); IRRI = फिलीपींस; IITA = नाइजीरिया; CIAT = कोलंबिया।\nCIMMYT - Mexico; IRRI - Philippines; IITA - Nigeria; CIAT - Colombia.", "s": "GAG", "lv": "Easy", "src": "CGIAR (cgiar.org); CIMMYT (cimmyt.org)", "cls": "New - PYQ pattern"}, {"q": "अंतरराष्ट्रीय चावल अनुसंधान संस्थान (IRRI) कहाँ स्थित है?\nWhere is the International Rice Research Institute (IRRI) located?", "o": ["लॉस बानोस, फिलीपींस / Los Banos, Philippines", "कोलंबो, श्रीलंका / Colombo, Sri Lanka", "हैदराबाद, भारत / Hyderabad, India", "बेरूत, लेबनान / Beirut, Lebanon"], "a": 0, "e": "IRRI (1960) लॉस बानोस, फिलीपींस में है। IWMI = कोलंबो; ICRISAT = पाटनचेरु (हैदराबाद); ICARDA का मुख्यालय बेरूत (लेबनान)।\nIRRI (1960) - Los Banos, Philippines. IWMI - Colombo; ICRISAT - Patancheru; ICARDA HQ - Beirut.", "s": "GAG", "lv": "Easy", "src": "IRRI (irri.org); CGIAR (cgiar.org)", "cls": "New - PYQ pattern"}, {"q": "ICRISAT का मुख्यालय कहाँ है?\nWhere is the headquarters of ICRISAT?", "o": ["इबादान, नाइजीरिया / Ibadan, Nigeria", "नैरोबी, केन्या / Nairobi, Kenya", "पाटनचेरु, तेलंगाना / Patancheru, Telangana", "लॉस बानोस / Los Banos"], "a": 2, "e": "ICRISAT (1972) पाटनचेरु, हैदराबाद (तेलंगाना) में है - भारत में स्थित एकमात्र CGIAR मुख्यालय। IITA = इबादान।\nICRISAT (1972) is at Patancheru, Hyderabad - the only CGIAR centre headquartered in India. IITA - Ibadan.", "s": "GAG", "lv": "Easy", "src": "ICRISAT (icrisat.org)", "cls": "New - PYQ pattern"}]}, {"id": "ICAR01-P2", "series": "icar-t3t4", "title": "Test 01 Paper II - Paper II (Mains): Group A Agriculture, all 20 units (FREE)", "free": true, "rel": "2026-11-16", "fixed": true, "dur": 120, "mpq": 3, "neg": 1, "questions": [{"q": "वर्टिसोल (काली मिट्टी) में मुख्य रूप से कौन-सा मृत्तिका खनिज (Clay mineral) पाया जाता है?\nThe dominant clay mineral in Vertisols (black soils) is", "o": ["केओलिनाइट / Kaolinite", "इलाइट / Illite", "मॉन्टमोरिलोनाइट / Montmorillonite", "क्लोराइट / Chlorite"], "a": 2, "e": "वर्टिसोल में 2:1 फैलने वाला मॉन्टमोरिलोनाइट (स्मेक्टाइट) प्रमुख है, इसलिए सूखने पर गहरी दरारें पड़ती हैं।\nVertisols are dominated by expanding 2:1 montmorillonite (smectite), which causes deep cracks on drying.", "s": "SOIL", "lv": "Easy", "src": "Indian Society of Soil Science, Fundamentals of Soil Science (ISSS, New Delhi); Brady & Weil, The Nature and Properties of Soils", "cls": "New - PYQ pattern"}, {"q": "खनिज मृदाओं का औसत कण घनत्व (Particle density) सामान्यतः माना जाता है\nThe average particle density of mineral soils is taken as", "o": ["1.33 g/cm³", "2.65 g/cm³", "3.50 g/cm³", "1.00 g/cm³"], "a": 1, "e": "क्वार्ट्ज़-प्रधान खनिज मृदाओं का औसत कण घनत्व 2.65 g/cm³ है; स्थूल घनत्व सामान्यतः 1.1-1.6 g/cm³।\nAverage particle density of quartz-dominated mineral soils is 2.65 g/cm³; bulk density is usually 1.1-1.6 g/cm³.", "s": "SOIL", "lv": "Easy", "src": "Indian Society of Soil Science, Fundamentals of Soil Science (ISSS, New Delhi); Brady & Weil, The Nature and Properties of Soils", "cls": "New - PYQ pattern"}, {"q": "किसी मृदा का स्थूल घनत्व 1.3 g/cm³ और कण घनत्व 2.6 g/cm³ है। उसकी सरंध्रता (Porosity) कितनी है?\nA soil has bulk density 1.3 g/cm³ and particle density 2.6 g/cm³. Its porosity is", "o": ["50%", "30%", "65%", "40%"], "a": 0, "e": "सरंध्रता = (1 - BD/PD) × 100 = (1 - 1.3/2.6) × 100 = 50%।\nPorosity = (1 - BD/PD) × 100 = (1 - 0.5) × 100 = 50%.", "s": "SOIL", "lv": "Moderate", "src": "Indian Society of Soil Science, Fundamentals of Soil Science (ISSS, New Delhi); Brady & Weil, The Nature and Properties of Soils", "cls": "New - PYQ pattern"}, {"q": "ESP > 15 और pH > 8.5 वाली क्षारीय (Sodic) मृदा के सुधार के लिए सबसे प्रचलित सुधारक है\nThe most common amendment for reclaiming sodic soils (ESP > 15, pH > 8.5) is", "o": ["चूना / Lime", "जिप्सम / Gypsum", "डोलोमाइट / Dolomite", "राख / Wood ash"], "a": 1, "e": "जिप्सम (CaSO4.2H2O) का Ca विनिमय स्थलों से Na को हटाता है, जो निक्षालन से बह जाता है। चूना अम्लीय मृदा के लिए है।\nCa from gypsum replaces exchangeable Na, which is leached out. Lime is used for acid soils.", "s": "SOIL", "lv": "Easy", "src": "Indian Society of Soil Science, Fundamentals of Soil Science (ISSS, New Delhi); Brady & Weil, The Nature and Properties of Soils; ICAR-CSSRI, Karnal", "cls": "New - PYQ pattern"}, {"q": "एजोला (Azolla) के साथ सहजीवी नाइट्रोजन स्थिरीकरण करने वाला जीव है\nThe nitrogen-fixing symbiont of Azolla is", "o": ["Anabaena azollae", "Rhizobium", "Azotobacter", "Frankia"], "a": 0, "e": "एजोला की पत्तियों की गुहाओं में नील-हरित शैवाल Anabaena azollae रहता है; धान में जैव उर्वरक के रूप में प्रयोग।\nThe cyanobacterium Anabaena azollae lives in the leaf cavities of Azolla; used as a biofertiliser in rice.", "s": "SOIL", "lv": "Easy", "src": "Indian Society of Soil Science, Fundamentals of Soil Science (ISSS, New Delhi); Brady & Weil, The Nature and Properties of Soils; Subba Rao, Soil Microbiology", "cls": "New - PYQ pattern"}, {"q": "92 kg नाइट्रोजन प्रति हेक्टेयर देने के लिए कितना यूरिया (46% N) चाहिए?\nHow much urea (46% N) is needed to supply 92 kg N per hectare?", "o": ["100 kg", "150 kg", "200 kg", "250 kg"], "a": 2, "e": "यूरिया = 92 × 100/46 = 200 kg।\nUrea = 92 × 100/46 = 200 kg.", "s": "SOIL", "lv": "Moderate", "src": "Fertiliser (Control) Order, 1985 - urea 46% N; calculation", "cls": "New - PYQ pattern"}, {"q": "धान का 'खैरा' (Khaira) रोग किस पोषक तत्व की कमी से होता है?\n'Khaira' disease of rice is caused by deficiency of", "o": ["लोहा / Iron", "बोरॉन / Boron", "जस्ता / Zinc", "मैंगनीज़ / Manganese"], "a": 2, "e": "खैरा = जिंक की कमी (Y.L. Nene, 1966, पंतनगर); उपचार ZnSO4।\nKhaira is zinc deficiency (Y.L. Nene, 1966, Pantnagar); corrected with ZnSO4.", "s": "SOIL", "lv": "Easy", "src": "Nene, Y.L. (1966), Indian Phytopathology 19: 136-139; Indian Society of Soil Science, Fundamentals of Soil Science (ISSS, New Delhi); Brady & Weil, The Nature and Properties of Soils", "cls": "New - PYQ pattern"}, {"q": "सार्वत्रिक मृदा क्षति समीकरण (USLE: A = R K L S C P) में 'K' क्या दर्शाता है?\nIn the Universal Soil Loss Equation (A = R K L S C P), 'K' stands for", "o": ["वर्षा अपरदकता / Rainfall erosivity", "फसल प्रबंधन कारक / Crop management factor", "संरक्षण पद्धति कारक / Conservation practice factor", "मृदा अपरदनीयता / Soil erodibility"], "a": 3, "e": "R = वर्षा अपरदकता, K = मृदा अपरदनीयता, LS = ढाल लंबाई-तीव्रता, C = फसल, P = संरक्षण पद्धति (Wischmeier & Smith)।\nR erosivity, K soil erodibility, LS slope length-steepness, C cover-management, P support practice (Wischmeier & Smith).", "s": "SOIL", "lv": "Moderate", "src": "Wischmeier & Smith (1978), USDA Agriculture Handbook 537; Michael & Ojha, Principles of Agricultural Engineering, Vol. I & II", "cls": "New - PYQ pattern"}, {"q": "मृदा में जैविक कार्बन ज्ञात करने की 'आर्द्र ऑक्सीकरण' (Wet oxidation) विधि किसने दी?\nThe wet oxidation method for soil organic carbon was given by", "o": ["ओल्सेन / Olsen", "जैक्सन / Jackson", "ब्रे व कर्ट्ज़ / Bray and Kurtz", "वॉकली व ब्लैक / Walkley and Black"], "a": 3, "e": "Walkley & Black (1934): K2Cr2O7 + H2SO4 से जैविक कार्बन का ऑक्सीकरण।\nWalkley & Black (1934): organic carbon oxidised by K2Cr2O7 + H2SO4.", "s": "SOIL", "lv": "Easy", "src": "Walkley & Black (1934), Soil Science 37: 29-38", "cls": "New - PYQ pattern"}, {"q": "गेहूँ में सिंचाई की सबसे क्रांतिक अवस्था कौन-सी है?\nThe most critical stage for irrigation in wheat is", "o": ["कल्ले निकलना / Tillering", "शीर्ष जड़ प्रारंभ (CRI) / Crown root initiation", "बाली निकलना / Heading", "दानों का दूधिया होना / Milking"], "a": 1, "e": "CRI (बुवाई के 20-25 दिन बाद) गेहूँ में सिंचाई की सबसे क्रांतिक अवस्था है।\nCRI (20-25 days after sowing) is the most critical irrigation stage in wheat.", "s": "AGRO", "lv": "Easy", "src": "ICAR Handbook of Agriculture (ICAR-DKMA); Reddy & Reddi, Principles of Agronomy; ICAR-IIWBR, Karnal", "cls": "New - PYQ pattern"}, {"q": "समय पर बोए गए सिंचित गेहूँ की सामान्य बीज दर है\nThe normal seed rate of timely sown irrigated wheat is", "o": ["40 kg/ha", "100 kg/ha", "150 kg/ha", "200 kg/ha"], "a": 1, "e": "समय पर बुवाई में 100 kg/ha; देर से बुवाई में 125 kg/ha तक बढ़ाई जाती है।\nTimely sown: 100 kg/ha; late sown: increased to about 125 kg/ha.", "s": "AGRO", "lv": "Easy", "src": "ICAR Handbook of Agriculture (ICAR-DKMA); Reddy & Reddi, Principles of Agronomy; ICAR-IIWBR package of practices", "cls": "New - PYQ pattern"}, {"q": "धान सघनीकरण प्रणाली (SRI) सर्वप्रथम किस देश में विकसित हुई?\nThe System of Rice Intensification (SRI) was first developed in", "o": ["फिलीपींस / Philippines", "जापान / Japan", "भारत / India", "मेडागास्कर / Madagascar"], "a": 3, "e": "SRI को फादर हेनरी डी लौलानी ने 1983 में मेडागास्कर में विकसित किया।\nSRI was developed by Fr. Henri de Laulanie in Madagascar in 1983.", "s": "AGRO", "lv": "Moderate", "src": "ICAR-NRRI, Cuttack; Uphoff (2002), SRI-Rice, Cornell University", "cls": "New - PYQ pattern"}, {"q": "योजना आयोग (1989) ने भारत को कितने कृषि-जलवायु क्षेत्रों (Agro-climatic regions) में बाँटा?\nThe Planning Commission (1989) divided India into how many agro-climatic regions?", "o": ["15", "20", "127", "8"], "a": 0, "e": "योजना आयोग = 15 कृषि-जलवायु क्षेत्र; NARP = 127 कृषि-जलवायु ज़ोन; NBSS&LUP = 20 कृषि-पारिस्थितिक क्षेत्र।\nPlanning Commission - 15 regions; NARP - 127 zones; NBSS&LUP - 20 agro-ecological regions.", "s": "AGRO", "lv": "Moderate", "src": "ICAR Handbook of Agriculture (ICAR-DKMA); Reddy & Reddi, Principles of Agronomy; Planning Commission (1989), Agro-climatic Regional Planning", "cls": "New - PYQ pattern"}, {"q": "परिशुद्ध खेती (Precision farming) में 'VRT' का अर्थ है\nIn precision farming, 'VRT' stands for", "o": ["Vertical Root Training", "Variable Rate Technology", "Volume Regulated Tillage", "Varietal Release Test"], "a": 1, "e": "VRT से खेत के अलग-अलग भागों में आवश्यकता अनुसार बीज, उर्वरक, रसायन की मात्रा बदली जाती है।\nVRT varies the rate of seed, fertiliser or chemicals across a field according to need.", "s": "AGRO", "lv": "Easy", "src": "ICAR-IARI, Precision Agriculture; Srinivasan (ed.), Handbook of Precision Agriculture", "cls": "New - PYQ pattern"}, {"q": "राष्ट्रीय जैविक उत्पादन कार्यक्रम (NPOP) किस संस्था द्वारा लागू किया जाता है?\nThe National Programme for Organic Production (NPOP) is implemented by", "o": ["FSSAI", "NABARD", "ICAR", "APEDA"], "a": 3, "e": "NPOP (2001) वाणिज्य मंत्रालय के अंतर्गत APEDA लागू करता है; निर्यात हेतु जैविक प्रमाणन मानक तय करता है।\nNPOP (2001) is implemented by APEDA under the Ministry of Commerce; it sets organic certification standards for export.", "s": "AGRO", "lv": "Moderate", "src": "APEDA (apeda.gov.in) - NPOP", "cls": "New - PYQ pattern"}, {"q": "गन्ने का व्यावसायिक प्रवर्धन किसके द्वारा किया जाता है?\nSugarcane is commercially propagated by", "o": ["तने के टुकड़े (सेट्स) / Stem cuttings (setts)", "बीज / True seeds", "अंतःभूस्तारी / Suckers", "प्रकंद / Rhizomes"], "a": 0, "e": "गन्ना 2-3 आँख वाले तने के टुकड़ों (सेट्स) से बोया जाता है; सच्चा बीज केवल प्रजनन कार्य में।\nSugarcane is planted with 2-3 budded setts; true seed is used only in breeding.", "s": "AGRO", "lv": "Easy", "src": "ICAR-IISR, Lucknow; ICAR-SBI, Coimbatore", "cls": "New - PYQ pattern"}, {"q": "'चारा फसलों का राजा' बरसीम का वानस्पतिक नाम है\nThe botanical name of berseem, the 'king of fodder crops', is", "o": ["Medicago sativa", "Sorghum sudanense", "Trifolium alexandrinum", "Pennisetum purpureum"], "a": 2, "e": "बरसीम = Trifolium alexandrinum; लूसर्न (रिजका) = Medicago sativa ('चारे की रानी'); नेपियर = Pennisetum purpureum।\nBerseem - Trifolium alexandrinum; lucerne - Medicago sativa ('queen of fodders'); Napier - Pennisetum purpureum.", "s": "AGRO", "lv": "Easy", "src": "ICAR-IGFRI, Jhansi; ICAR Handbook of Agriculture (ICAR-DKMA); Reddy & Reddi, Principles of Agronomy", "cls": "New - PYQ pattern"}, {"q": "धान में 'हॉपर बर्न' (Hopper burn) किस कीट से होता है?\n'Hopper burn' in rice is caused by", "o": ["तना छेदक / Stem borer", "भूरा फुदका / Brown planthopper", "गंधी बग / Gundhi bug", "पत्ती लपेटक / Leaf folder"], "a": 1, "e": "भूरा फुदका (Nilaparvata lugens) पौधे के आधार से रस चूसता है, जिससे गोलाकार झुलसे क्षेत्र (हॉपर बर्न) बनते हैं।\nBrown planthopper (Nilaparvata lugens) sucks sap at the plant base, producing circular dried patches - hopper burn.", "s": "PP", "lv": "Easy", "src": "R.S. Singh, Plant Diseases; Dhaliwal & Arora, Integrated Pest Management (Kalyani); ICAR-NRRI", "cls": "New - PYQ pattern"}, {"q": "कपास के गुलाबी सूंडी (Pink bollworm) का वैज्ञानिक नाम है\nThe scientific name of the pink bollworm of cotton is", "o": ["Pectinophora gossypiella", "Helicoverpa armigera", "Earias vittella", "Spodoptera litura"], "a": 0, "e": "गुलाबी सूंडी = Pectinophora gossypiella; अमेरिकन सूंडी = Helicoverpa armigera; चित्तीदार सूंडी = Earias vittella।\nPink bollworm - Pectinophora gossypiella; American bollworm - Helicoverpa; spotted bollworm - Earias.", "s": "PP", "lv": "Easy", "src": "R.S. Singh, Plant Diseases; Dhaliwal & Arora, Integrated Pest Management (Kalyani); ICAR-CICR, Nagpur", "cls": "New - PYQ pattern"}, {"q": "1845-46 के आयरिश अकाल का कारण बना आलू का पछेती झुलसा रोग किससे होता है?\nLate blight of potato, which caused the Irish famine of 1845-46, is caused by", "o": ["Phytophthora infestans", "Alternaria solani", "Ralstonia solanacearum", "Streptomyces scabies"], "a": 0, "e": "पछेती झुलसा = Phytophthora infestans (ऊमाइसीट); अगेती झुलसा = Alternaria solani।\nLate blight - Phytophthora infestans (oomycete); early blight - Alternaria solani.", "s": "PP", "lv": "Easy", "src": "R.S. Singh, Plant Diseases; Dhaliwal & Arora, Integrated Pest Management (Kalyani); ICAR-CPRI, Shimla", "cls": "New - PYQ pattern"}, {"q": "Bt कपास मुख्य रूप से किन कीटों से सुरक्षा देता है?\nBt cotton mainly protects against", "o": ["सफेद मक्खी / Whitefly", "माहू / Aphids", "मिली बग / Mealy bug", "सूंडी (बॉलवर्म) / Bollworms"], "a": 3, "e": "Bacillus thuringiensis का Cry प्रोटीन लेपिडॉप्टेरा सूंडियों की मध्यांत्र को नष्ट करता है; रस चूसक कीटों पर असर नहीं।\nCry proteins of Bacillus thuringiensis destroy the midgut of lepidopteran larvae; no effect on sucking pests.", "s": "PP", "lv": "Easy", "src": "R.S. Singh, Plant Diseases; Dhaliwal & Arora, Integrated Pest Management (Kalyani); ICAR-CICR, Nagpur", "cls": "New - PYQ pattern"}, {"q": "ट्राइकोग्रामा (Trichogramma) किस प्रकार का परजीवी है?\nTrichogramma is a/an", "o": ["अंड परजीवी / Egg parasitoid", "लार्वा परजीवी / Larval parasitoid", "प्यूपा परजीवी / Pupal parasitoid", "परभक्षी / Predator"], "a": 0, "e": "ट्राइकोग्रामा कीटों के अंडों में अपने अंडे देता है; Trichocard के रूप में गन्ना व धान के बेधकों के विरुद्ध।\nTrichogramma lays eggs inside host eggs; released as Trichocards against borers of sugarcane and rice.", "s": "PP", "lv": "Easy", "src": "ICAR-NBAIR, Bengaluru; R.S. Singh, Plant Diseases; Dhaliwal & Arora, Integrated Pest Management (Kalyani)", "cls": "New - PYQ pattern"}, {"q": "भंडारित अनाज का 'खपरा भृंग' (Khapra beetle) है\nThe 'khapra beetle' of stored grain is", "o": ["Trogoderma granarium", "Sitophilus oryzae", "Rhyzopertha dominica", "Tribolium castaneum"], "a": 0, "e": "खपरा = Trogoderma granarium (केवल लार्वा हानिकारक); चावल घुन = Sitophilus; छोटा बेधक = Rhyzopertha; लाल आटा भृंग = Tribolium।\nKhapra - Trogoderma granarium (only larvae damage); rice weevil - Sitophilus; lesser grain borer - Rhyzopertha; red flour beetle - Tribolium.", "s": "PP", "lv": "Moderate", "src": "R.S. Singh, Plant Diseases; Dhaliwal & Arora, Integrated Pest Management (Kalyani)", "cls": "New - PYQ pattern"}, {"q": "आलू के पछेती झुलसा रोग के पूर्वानुमान के लिए ICAR-CPRI द्वारा विकसित मॉडल है\nThe forecasting model developed by ICAR-CPRI for late blight of potato is", "o": ["BLITECAST", "JHULSACAST", "EPIDEM", "SIMCAST"], "a": 1, "e": "JHULSACAST (ICAR-CPRI, शिमला) भारत की परिस्थितियों के लिए; BLITECAST अमेरिका में विकसित मॉडल है।\nJHULSACAST was developed by ICAR-CPRI for Indian conditions; BLITECAST is a US model.", "s": "PP", "lv": "Moderate", "src": "ICAR-CPRI, Shimla (cpri.icar.gov.in)", "cls": "New - PYQ pattern"}, {"q": "इमिडाक्लोप्रिड (नियोनिकोटिनॉइड) की क्रिया-विधि है\nThe mode of action of imidacloprid (a neonicotinoid) is", "o": ["निकोटिनिक एसिटाइलकोलीन रिसेप्टर एगोनिस्ट / Nicotinic acetylcholine receptor agonist", "एसिटाइलकोलिनएस्टरेज़ अवरोध / Acetylcholinesterase inhibition", "GABA-क्लोराइड चैनल अवरोध / GABA-gated chloride channel blocker", "सोडियम चैनल मॉड्यूलेटर / Sodium channel modulator"], "a": 0, "e": "नियोनिकोटिनॉइड nAChR पर एगोनिस्ट (IRAC समूह 4A); OP/कार्बामेट = AChE अवरोधक; पाइरेथ्रॉइड = सोडियम चैनल।\nNeonicotinoids are nAChR agonists (IRAC group 4A); OPs/carbamates inhibit AChE; pyrethroids act on sodium channels.", "s": "PP", "lv": "Moderate", "src": "IRAC Mode of Action Classification (irac-online.org)", "cls": "New - PYQ pattern"}, {"q": "फसलों के 'उद्भव केंद्र' (Centres of origin) की अवधारणा किसने दी?\nWho proposed the concept of centres of origin of crop plants?", "o": ["डार्विन / Darwin", "डी कैंडोल / De Candolle", "हार्लन / Harlan", "वाविलोव / Vavilov"], "a": 3, "e": "एन.आई. वाविलोव ने 8 मुख्य उद्भव केंद्र बताए (भारत = हिंदुस्तान केंद्र)।\nN.I. Vavilov proposed 8 main centres of origin (India - Hindustan centre).", "s": "GPB", "lv": "Easy", "src": "B.D. Singh, Plant Breeding: Principles and Methods; B.D. Singh, Fundamentals of Genetics (Kalyani)", "cls": "New - PYQ pattern"}, {"q": "'हेटेरोसिस' (Heterosis) शब्द किसने दिया?\nWho coined the term 'heterosis'?", "o": ["जी.एच. शल / G.H. Shull", "ई.एम. ईस्ट / E.M. East", "डी.एफ. जोन्स / D.F. Jones", "सी.बी. डेवनपोर्ट / C.B. Davenport"], "a": 0, "e": "शल (1914) ने 'heterosis' शब्द दिया; जोन्स (1918) ने द्विसंकर (double cross) विधि दी।\nShull (1914) coined 'heterosis'; Jones (1918) proposed the double cross.", "s": "GPB", "lv": "Easy", "src": "B.D. Singh, Plant Breeding: Principles and Methods; B.D. Singh, Fundamentals of Genetics (Kalyani)", "cls": "New - PYQ pattern"}, {"q": "शुद्ध वंशक्रम चयन (Pure line selection) मुख्य रूप से किन फसलों में अपनाया जाता है?\nPure line selection is mainly used in", "o": ["परपरागित फसलें / Cross-pollinated crops", "अलैंगिक प्रवर्धित फसलें / Asexually propagated crops", "केवल संकर फसलें / Only hybrid crops", "स्वपरागित फसलें / Self-pollinated crops"], "a": 3, "e": "स्वपरागित फसलें प्राकृतिक रूप से समयुग्मजी होती हैं, अतः एक पौधे की संतति (शुद्ध वंशक्रम) से किस्म बनती है।\nSelf-pollinated crops are naturally homozygous, so a variety can be developed from the progeny of a single plant (pure line).", "s": "GPB", "lv": "Easy", "src": "B.D. Singh, Plant Breeding: Principles and Methods; B.D. Singh, Fundamentals of Genetics (Kalyani)", "cls": "New - PYQ pattern"}, {"q": "CRISPR-Cas9 जीनोम संपादन तकनीक के विकास के लिए 2020 का रसायन नोबेल पुरस्कार किसे मिला?\nWho received the 2020 Nobel Prize in Chemistry for developing CRISPR-Cas9 genome editing?", "o": ["वाटसन व क्रिक / Watson and Crick", "जेनिफर डाउडना व इमैनुएल शार्पेंटियर / Jennifer Doudna and Emmanuelle Charpentier", "कैरी मुलिस / Kary Mullis", "नॉर्मन बोरलॉग / Norman Borlaug"], "a": 1, "e": "डाउडना व शार्पेंटियर (2012 शोध) को 2020 का रसायन नोबेल मिला। मुलिस = PCR; बोरलॉग = 1970 शांति नोबेल।\nDoudna and Charpentier (2012 work) won the 2020 Chemistry Nobel. Mullis - PCR; Borlaug - 1970 Peace Nobel.", "s": "GPB", "lv": "Moderate", "src": "NobelPrize.org - Nobel Prize in Chemistry 2020", "cls": "New - PYQ pattern"}, {"q": "निम्नलिखित में से कौन-सा PCR-आधारित, सह-प्रभावी (Co-dominant) आणविक मार्कर है?\nWhich of the following is a PCR-based co-dominant molecular marker?", "o": ["RAPD", "AFLP", "ISSR", "SSR"], "a": 3, "e": "SSR (माइक्रोसैटेलाइट) सह-प्रभावी है और विषमयुग्मजी पहचान सकता है; RAPD, AFLP, ISSR प्रभावी (dominant) मार्कर हैं।\nSSR (microsatellite) is co-dominant and distinguishes heterozygotes; RAPD, AFLP and ISSR are dominant markers.", "s": "GPB", "lv": "Moderate", "src": "B.D. Singh, Plant Breeding: Principles and Methods; B.D. Singh, Fundamentals of Genetics (Kalyani)", "cls": "New - PYQ pattern"}, {"q": "द्विगुणित अगुणित (Doubled haploid) तकनीक का मुख्य लाभ है\nThe main advantage of the doubled haploid technique is", "o": ["संकर ओज बढ़ाना / Increasing heterosis", "एक ही पीढ़ी में पूर्ण समयुग्मजता / Complete homozygosity in one generation", "बहुगुणिता उत्पन्न करना / Inducing polyploidy", "उत्परिवर्तन दर बढ़ाना / Increasing mutation rate"], "a": 1, "e": "अगुणित पौधे के गुणसूत्र दोगुने (colchicine) करने से एक पीढ़ी में शुद्ध (समयुग्मजी) वंशक्रम मिलता है, जिससे प्रजनन चक्र छोटा होता है।\nDoubling the chromosomes of a haploid (colchicine) gives a fully homozygous line in one generation, shortening the breeding cycle.", "s": "GPB", "lv": "Moderate", "src": "B.D. Singh, Plant Breeding: Principles and Methods; B.D. Singh, Fundamentals of Genetics (Kalyani)", "cls": "New - PYQ pattern"}, {"q": "निषेचन के बिना बीज बनना कहलाता है\nFormation of seed without fertilisation is called", "o": ["अनिषेकफलन / Parthenocarpy", "बहुभ्रूणता / Polyembryony", "स्व-असंगतता / Self-incompatibility", "असंगजनन / Apomixis"], "a": 3, "e": "असंगजनन (Winkler, 1908) में बीज बनता है पर निषेचन नहीं होता; अनिषेकफलन में फल बनता है पर बीज नहीं।\nIn apomixis (Winkler, 1908) seed forms without fertilisation; in parthenocarpy fruit forms without seed.", "s": "GPB", "lv": "Easy", "src": "B.D. Singh, Plant Breeding: Principles and Methods; B.D. Singh, Fundamentals of Genetics (Kalyani)", "cls": "New - PYQ pattern"}, {"q": "आम की किस्म 'आम्रपाली' किस संकरण से विकसित हुई?\nThe mango variety 'Amrapali' was developed from which cross?", "o": ["नीलम × दशहरी / Neelum × Dashehari", "दशहरी × नीलम / Dashehari × Neelum", "लंगड़ा × अल्फांसो / Langra × Alphonso", "तोतापुरी × बंगनपल्ली / Totapuri × Banganapalli"], "a": 1, "e": "आम्रपाली = दशहरी × नीलम (IARI, 1971, बौनी, नियमित फलन); मल्लिका = नीलम × दशहरी।\nAmrapali - Dashehari × Neelum (IARI, 1971; dwarf, regular bearing); Mallika - Neelum × Dashehari.", "s": "HORT", "lv": "Moderate", "src": "K.V. Peter (ed.), Basics of Horticulture; ICAR Handbook of Horticulture (ICAR-DKMA); ICAR-IARI", "cls": "New - PYQ pattern"}, {"q": "पपेन (Papain) एंजाइम किससे प्राप्त होता है?\nThe enzyme papain is obtained from", "o": ["पके पपीते के बीज / Seeds of ripe papaya", "कच्चे पपीते के फल का लेटेक्स / Latex of unripe papaya fruit", "पपीते की पत्तियाँ / Papaya leaves", "पपीते की जड़ / Papaya roots"], "a": 1, "e": "कच्चे हरे पपीते के फल पर चीरा लगाकर लेटेक्स निकाला जाता है, जिसे सुखाकर पपेन बनता है (CO-2, CO-5 पपेन हेतु)।\nLatex tapped from unripe green fruits is dried to give papain (varieties like CO-2, CO-5).", "s": "HORT", "lv": "Easy", "src": "K.V. Peter (ed.), Basics of Horticulture; ICAR Handbook of Horticulture (ICAR-DKMA)", "cls": "New - PYQ pattern"}, {"q": "निम्नलिखित में से कौन-सा फल अक्लाइमैक्टेरिक (Non-climacteric) है?\nWhich of the following fruits is non-climacteric?", "o": ["आम / Mango", "केला / Banana", "अंगूर / Grape", "पपीता / Papaya"], "a": 2, "e": "अंगूर, नींबू वर्गीय, अनार, लीची अक्लाइमैक्टेरिक हैं (तुड़ाई के बाद नहीं पकते); आम, केला, पपीता क्लाइमैक्टेरिक हैं।\nGrape, citrus, pomegranate and litchi are non-climacteric; mango, banana and papaya are climacteric.", "s": "HORT", "lv": "Moderate", "src": "K.V. Peter (ed.), Basics of Horticulture; ICAR Handbook of Horticulture (ICAR-DKMA); Wills et al., Postharvest", "cls": "New - PYQ pattern"}, {"q": "'मसालों की रानी' (Queen of spices) किसे कहा जाता है?\nWhich is called the 'queen of spices'?", "o": ["काली मिर्च / Black pepper", "लौंग / Clove", "छोटी इलायची / Small cardamom", "केसर / Saffron"], "a": 2, "e": "छोटी इलायची (Elettaria cardamomum) = मसालों की रानी; काली मिर्च = मसालों का राजा।\nSmall cardamom (Elettaria cardamomum) is the queen of spices; black pepper is the king.", "s": "HORT", "lv": "Easy", "src": "Spices Board India (indianspices.com); ICAR-IISR, Kozhikode", "cls": "New - PYQ pattern"}, {"q": "भारत में पॉलीहाउस के आवरण (Cladding) के लिए सामान्यतः किस मोटाई की UV-स्थिरीकृत पॉलीथीन फिल्म प्रयोग होती है?\nThe UV-stabilised polyethylene film commonly used for polyhouse cladding in India is of thickness", "o": ["50 माइक्रॉन / 50 micron", "100 माइक्रॉन / 100 micron", "200 माइक्रॉन / 200 micron", "500 माइक्रॉन / 500 micron"], "a": 2, "e": "पॉलीहाउस में सामान्यतः 200 माइक्रॉन (800 गेज) UV-स्थिरीकृत LDPE फिल्म लगाई जाती है।\nPolyhouses normally use 200 micron (800 gauge) UV-stabilised LDPE film.", "s": "HORT", "lv": "Moderate", "src": "National Horticulture Board, protected cultivation guidelines (nhb.gov.in); NCPAH", "cls": "New - PYQ pattern"}, {"q": "गुलाब का तेल (Rose oil/attar) मुख्य रूप से किस प्रजाति से प्राप्त होता है?\nRose oil (attar) is mainly obtained from", "o": ["Rosa indica", "Rosa damascena", "Rosa multiflora", "Rosa chinensis"], "a": 1, "e": "दमिश्क गुलाब (Rosa damascena) सुगंधित तेल व गुलाब जल का मुख्य स्रोत है; भारत में कन्नौज प्रसिद्ध।\nThe Damask rose (Rosa damascena) is the main source of rose oil and rose water; Kannauj is famous in India.", "s": "HORT", "lv": "Moderate", "src": "CSIR-CIMAP, Lucknow; K.V. Peter (ed.), Basics of Horticulture; ICAR Handbook of Horticulture (ICAR-DKMA)", "cls": "New - PYQ pattern"}, {"q": "ईसबगोल (Isabgol) का वानस्पतिक नाम है\nThe botanical name of isabgol is", "o": ["Withania somnifera", "Ocimum sanctum", "Mentha arvensis", "Plantago ovata"], "a": 3, "e": "ईसबगोल = Plantago ovata (बीज की भूसी औषधीय); अश्वगंधा = Withania; तुलसी = Ocimum; मेंथा = Mentha arvensis।\nIsabgol - Plantago ovata (seed husk is medicinal); ashwagandha - Withania; tulsi - Ocimum; menthol mint - Mentha arvensis.", "s": "HORT", "lv": "Easy", "src": "ICAR-DMAPR, Anand; National Medicinal Plants Board (nmpb.nic.in)", "cls": "New - PYQ pattern"}, {"q": "अर्धसूत्री विभाजन में जीन विनिमय (Crossing over) किस अवस्था में होता है?\nCrossing over in meiosis takes place during", "o": ["लेप्टोटीन / Leptotene", "ज़ाइगोटीन / Zygotene", "डिप्लोटीन / Diplotene", "पैकीटीन / Pachytene"], "a": 3, "e": "पैकीटीन में समजात गुणसूत्रों के बीच विनिमय होता है; डिप्लोटीन में किएज़्मेटा दिखते हैं; ज़ाइगोटीन में सिनैप्सिस।\nCrossing over occurs at pachytene; chiasmata become visible at diplotene; synapsis occurs at zygotene.", "s": "GEN", "lv": "Moderate", "src": "B.D. Singh, Plant Breeding: Principles and Methods; B.D. Singh, Fundamentals of Genetics (Kalyani)", "cls": "New - PYQ pattern"}, {"q": "द्विसंकर (AaBb) के परीक्षण संकरण (Test cross) का लक्षणप्ररूपी अनुपात है\nThe phenotypic ratio of a dihybrid (AaBb) test cross is", "o": ["9 : 3 : 3 : 1", "3 : 1", "1 : 2 : 1", "1 : 1 : 1 : 1"], "a": 3, "e": "AaBb × aabb से चार प्रकार की संतति समान अनुपात में: 1 : 1 : 1 : 1।\nAaBb × aabb gives four phenotypes in equal proportion: 1 : 1 : 1 : 1.", "s": "GEN", "lv": "Easy", "src": "B.D. Singh, Plant Breeding: Principles and Methods; B.D. Singh, Fundamentals of Genetics (Kalyani)", "cls": "New - PYQ pattern"}, {"q": "प्रभावी प्रबलता (Dominant epistasis) में F2 का अनुपात होता है\nThe F2 ratio in dominant epistasis is", "o": ["9 : 7", "9 : 3 : 4", "15 : 1", "12 : 3 : 1"], "a": 3, "e": "प्रभावी प्रबलता = 12 : 3 : 1 (कद्दू का फल रंग); अप्रभावी = 9 : 3 : 4; द्विगुणित अप्रभावी (complementary) = 9 : 7; द्विगुणित प्रभावी = 15 : 1।\nDominant epistasis 12 : 3 : 1 (summer squash colour); recessive 9 : 3 : 4; complementary 9 : 7; duplicate dominant 15 : 1.", "s": "GEN", "lv": "Moderate", "src": "B.D. Singh, Plant Breeding: Principles and Methods; B.D. Singh, Fundamentals of Genetics (Kalyani)", "cls": "New - PYQ pattern"}, {"q": "2n - 1 गुणसूत्र संख्या वाले जीव को कहते हैं\nAn organism with chromosome number 2n - 1 is called", "o": ["न्यूलीसोमिक / Nullisomic", "ट्राइसोमिक / Trisomic", "टेट्रासोमिक / Tetrasomic", "मोनोसोमिक / Monosomic"], "a": 3, "e": "2n - 1 = मोनोसोमिक; 2n - 2 = न्यूलीसोमिक; 2n + 1 = ट्राइसोमिक; 2n + 2 = टेट्रासोमिक।\n2n - 1 monosomic; 2n - 2 nullisomic; 2n + 1 trisomic; 2n + 2 tetrasomic.", "s": "GEN", "lv": "Easy", "src": "B.D. Singh, Plant Breeding: Principles and Methods; B.D. Singh, Fundamentals of Genetics (Kalyani)", "cls": "New - PYQ pattern"}, {"q": "कोशिकाद्रव्यी नर बंध्यता (CMS) के लिए उत्तरदायी जीन मुख्य रूप से कहाँ स्थित होते हैं?\nThe genes responsible for cytoplasmic male sterility (CMS) are mainly located in", "o": ["केंद्रक / Nucleus", "राइबोसोम / Ribosomes", "माइटोकॉन्ड्रिया / Mitochondria", "गॉल्जी काय / Golgi bodies"], "a": 2, "e": "CMS माइटोकॉन्ड्रियल जीनोम (जैसे मक्का का T-urf13) से होती है और मातृ वंशागति दिखाती है; उर्वरता पुनःस्थापक (Rf) जीन केंद्रक में होते हैं।\nCMS arises from mitochondrial genes (e.g. T-urf13 in maize) and is maternally inherited; fertility restorer (Rf) genes are nuclear.", "s": "GEN", "lv": "Moderate", "src": "B.D. Singh, Plant Breeding: Principles and Methods; B.D. Singh, Fundamentals of Genetics (Kalyani)", "cls": "New - PYQ pattern"}, {"q": "ट्रिटिकेल (Triticale) किन दो फसलों के संकरण से बना मानव-निर्मित अनाज है?\nTriticale is a man-made cereal derived from crossing", "o": ["गेहूँ × राई / Wheat × Rye", "गेहूँ × जौ / Wheat × Barley", "राई × जई / Rye × Oat", "धान × गेहूँ / Rice × Wheat"], "a": 0, "e": "ट्रिटिकेल = Triticum (गेहूँ) × Secale (राई) का उभयद्विगुणित (amphiploid)।\nTriticale is an amphiploid of Triticum (wheat) × Secale (rye).", "s": "GEN", "lv": "Easy", "src": "B.D. Singh, Plant Breeding: Principles and Methods; B.D. Singh, Fundamentals of Genetics (Kalyani)", "cls": "New - PYQ pattern"}, {"q": "क्योटो प्रोटोकॉल किस वर्ष अपनाया गया?\nThe Kyoto Protocol was adopted in", "o": ["1992", "2005", "1997", "2015"], "a": 2, "e": "क्योटो प्रोटोकॉल 1997 में अपनाया गया और 2005 में लागू हुआ; UNFCCC = 1992; पेरिस समझौता = 2015।\nKyoto Protocol adopted 1997, in force 2005; UNFCCC 1992; Paris Agreement 2015.", "s": "ECOL", "lv": "Easy", "src": "UNFCCC (unfccc.int) - Kyoto Protocol", "cls": "New - PYQ pattern"}, {"q": "पेरिस समझौते (2015) का दीर्घकालिक तापमान लक्ष्य है\nThe long-term temperature goal of the Paris Agreement (2015) is to", "o": ["वृद्धि 3°C से नीचे रखना / Keep warming below 3°C", "उत्सर्जन 2030 तक शून्य करना / Reach zero emissions by 2030", "वृद्धि 2°C से काफी नीचे रखना और 1.5°C का प्रयास / Keep warming well below 2°C and pursue 1.5°C", "केवल विकसित देशों के उत्सर्जन घटाना / Cut emissions of developed countries only"], "a": 2, "e": "अनुच्छेद 2: पूर्व-औद्योगिक स्तर से वृद्धि 2°C से काफी नीचे, और 1.5°C तक सीमित करने का प्रयास।\nArticle 2: hold warming well below 2°C above pre-industrial levels and pursue efforts to limit it to 1.5°C.", "s": "ECOL", "lv": "Moderate", "src": "UNFCCC - Paris Agreement, Article 2", "cls": "New - PYQ pattern"}, {"q": "निम्नलिखित में से कौन-सी ग्रीनहाउस गैस नहीं है?\nWhich of the following is NOT a greenhouse gas?", "o": ["नाइट्रोजन (N2) / Nitrogen (N2)", "मीथेन / Methane", "नाइट्रस ऑक्साइड / Nitrous oxide", "कार्बन डाइऑक्साइड / Carbon dioxide"], "a": 0, "e": "N2 अवरक्त विकिरण नहीं सोखती, इसलिए ग्रीनहाउस गैस नहीं है; CO2, CH4, N2O प्रमुख GHG हैं।\nN2 does not absorb infrared radiation; CO2, CH4 and N2O are major GHGs.", "s": "ECOL", "lv": "Easy", "src": "IPCC AR6 WG1 (ipcc.ch)", "cls": "New - PYQ pattern"}, {"q": "NDVI (सामान्यीकृत अंतर वनस्पति सूचकांक) की गणना किन दो स्पेक्ट्रल बैंड से होती है?\nNDVI (Normalised Difference Vegetation Index) is calculated from which two spectral bands?", "o": ["नीला व हरा / Blue and Green", "लाल व निकट-अवरक्त / Red and Near-infrared", "हरा व तापीय अवरक्त / Green and Thermal infrared", "पराबैंगनी व लाल / Ultraviolet and Red"], "a": 1, "e": "NDVI = (NIR - Red)/(NIR + Red); स्वस्थ वनस्पति लाल को सोखती और NIR को परावर्तित करती है।\nNDVI = (NIR - Red)/(NIR + Red); healthy vegetation absorbs red and reflects NIR.", "s": "ECOL", "lv": "Moderate", "src": "ISRO-NRSC (nrsc.gov.in); Lillesand & Kiefer, Remote Sensing and Image Interpretation", "cls": "New - PYQ pattern"}, {"q": "कौन-सा पारिस्थितिक पिरामिड सदैव सीधा (Upright) होता है?\nWhich ecological pyramid is always upright?", "o": ["संख्या का पिरामिड / Pyramid of numbers", "जीवभार का पिरामिड / Pyramid of biomass", "ऊर्जा का पिरामिड / Pyramid of energy", "कोई नहीं / None"], "a": 2, "e": "हर पोषी स्तर पर ऊर्जा घटती है (10% नियम, लिंडमैन), अतः ऊर्जा पिरामिड कभी उल्टा नहीं होता।\nEnergy decreases at each trophic level (Lindeman's 10% law), so the energy pyramid is never inverted.", "s": "ECOL", "lv": "Easy", "src": "NCERT Biology Class XII, Ecosystem; Odum, Fundamentals of Ecology", "cls": "New - PYQ pattern"}, {"q": "निम्नलिखित में से किस सिंचाई विधि की जल अनुप्रयोग दक्षता सबसे अधिक है?\nWhich irrigation method has the highest water application efficiency?", "o": ["टपक सिंचाई / Drip irrigation", "बाढ़ सिंचाई / Flood irrigation", "कूँड़ सिंचाई / Furrow irrigation", "फव्वारा सिंचाई / Sprinkler irrigation"], "a": 0, "e": "टपक सिंचाई दक्षता लगभग 90-95%, फव्वारा लगभग 70-80%, सतही विधियाँ लगभग 40-60%।\nDrip about 90-95%, sprinkler about 70-80%, surface methods about 40-60%.", "s": "IRR", "lv": "Easy", "src": "Michael & Ojha, Principles of Agricultural Engineering, Vol. I & II; ICAR-IIWM, Bhubaneswar", "cls": "New - PYQ pattern"}, {"q": "सिंचाई जल का सोडियम अधिशोषण अनुपात (SAR) किस सूत्र से ज्ञात होता है? (सांद्रता meq/L में)\nThe sodium adsorption ratio (SAR) of irrigation water is (concentrations in meq/L)", "o": ["Na / (Ca + Mg)", "Na / √((Ca + Mg)/2)", "(Ca + Mg) / Na", "Na / √(Ca × Mg)"], "a": 1, "e": "SAR = Na⁺ / √((Ca²⁺ + Mg²⁺)/2); अधिक SAR से मृदा सोडिक होती है।\nSAR = Na⁺ / √((Ca²⁺ + Mg²⁺)/2); high SAR leads to sodicity.", "s": "IRR", "lv": "Moderate", "src": "USDA Handbook 60 (Richards, 1954); Indian Society of Soil Science, Fundamentals of Soil Science (ISSS, New Delhi); Brady & Weil, The Nature and Properties of Soils", "cls": "New - PYQ pattern"}, {"q": "सिंचाई निर्धारण (Irrigation scheduling) की IW/CPE विधि किस आधार पर है?\nThe IW/CPE approach of irrigation scheduling is based on", "o": ["मृदा नमी तनाव / Soil moisture tension", "जलवायवीय (पैन वाष्पीकरण) / Climatological - pan evaporation", "पौधे का रंग / Plant colour", "कैलेंडर दिनों / Calendar days"], "a": 1, "e": "IW/CPE = सिंचाई जल की गहराई / संचयी पैन वाष्पीकरण (Prihar et al., 1974); यह जलवायवीय विधि है।\nIW/CPE = depth of irrigation water / cumulative pan evaporation (Prihar et al., 1974) - a climatological approach.", "s": "IRR", "lv": "Moderate", "src": "ICAR Handbook of Agriculture (ICAR-DKMA); Reddy & Reddi, Principles of Agronomy; Reddy & Reddi, Principles of Agronomy", "cls": "New - PYQ pattern"}, {"q": "किसी फसल की उपज 4,000 kg/ha है और उसने 400 mm जल का उपयोग किया। जल उपयोग दक्षता (WUE) कितनी है?\nA crop yields 4,000 kg/ha using 400 mm of water. Its water use efficiency (WUE) is", "o": ["1 kg/ha-mm", "100 kg/ha-mm", "10 kg/ha-mm", "0.1 kg/ha-mm"], "a": 2, "e": "WUE = उपज / जल उपयोग = 4000/400 = 10 kg/ha-mm।\nWUE = yield / water used = 4000/400 = 10 kg/ha-mm.", "s": "IRR", "lv": "Moderate", "src": "ICAR Handbook of Agriculture (ICAR-DKMA); Reddy & Reddi, Principles of Agronomy", "cls": "New - PYQ pattern"}, {"q": "सरदार सरोवर परियोजना किस नदी पर है?\nThe Sardar Sarovar Project is on which river?", "o": ["ताप्ती / Tapi", "माही / Mahi", "नर्मदा / Narmada", "साबरमती / Sabarmati"], "a": 2, "e": "सरदार सरोवर बाँध नर्मदा नदी पर केवड़िया (गुजरात) में है।\nSardar Sarovar Dam is on the Narmada at Kevadia, Gujarat.", "s": "IRR", "lv": "Easy", "src": "Sardar Sarovar Narmada Nigam Ltd. (sardarsarovardam.org); Central Water Commission", "cls": "New - PYQ pattern"}, {"q": "C4 पौधों में CO2 स्थिरीकरण का प्रथम स्थायी उत्पाद है\nThe first stable product of CO2 fixation in C4 plants is", "o": ["3-फॉस्फोग्लिसरिक अम्ल / 3-PGA", "राइबुलोज बिसफॉस्फेट / RuBP", "ऑक्सैलोएसीटिक अम्ल / Oxaloacetic acid", "ग्लूकोज़ / Glucose"], "a": 2, "e": "C4 (हैच-स्लैक) पथ में PEP कार्बोक्सिलेज़ से 4-कार्बन OAA बनता है; C3 में 3-PGA।\nIn the C4 (Hatch-Slack) pathway PEP carboxylase forms 4-carbon OAA; in C3 it is 3-PGA.", "s": "PHY", "lv": "Easy", "src": "Taiz & Zeiger, Plant Physiology and Development (Sinauer); Jain, Fundamentals of Plant Physiology", "cls": "New - PYQ pattern"}, {"q": "निम्नलिखित में से कौन-सा अल्प-प्रकाशकालिक (Short-day) पौधा है?\nWhich of the following is a short-day plant?", "o": ["सोयाबीन / Soybean", "गेहूँ / Wheat", "जौ / Barley", "पालक / Spinach"], "a": 0, "e": "सोयाबीन (Biloxi), धान, तंबाकू (Maryland Mammoth) अल्प-प्रकाशकालिक; गेहूँ, जौ, पालक दीर्घ-प्रकाशकालिक (Garner & Allard, 1920)।\nSoybean (Biloxi), rice and tobacco are short-day; wheat, barley and spinach are long-day (Garner & Allard, 1920).", "s": "PHY", "lv": "Easy", "src": "Taiz & Zeiger, Plant Physiology and Development (Sinauer); Jain, Fundamentals of Plant Physiology", "cls": "New - PYQ pattern"}, {"q": "वसंतीकरण (Vernalization) का अर्थ है\nVernalization means", "o": ["प्रकाश द्वारा पुष्पन / Flowering induced by light", "बीज की सुप्तावस्था / Seed dormancy", "अधिक ताप से फल पकना / Ripening by high temperature", "निम्न ताप उपचार द्वारा पुष्पन को बढ़ावा / Promotion of flowering by low-temperature treatment"], "a": 3, "e": "वसंतीकरण (Lysenko, 1928) = शीत उपचार से पुष्पन को प्रेरित करना, जैसे शीतकालीन गेहूँ।\nVernalization (Lysenko, 1928) is promotion of flowering by cold treatment, e.g. winter wheat.", "s": "PHY", "lv": "Easy", "src": "Taiz & Zeiger, Plant Physiology and Development (Sinauer); Jain, Fundamentals of Plant Physiology", "cls": "New - PYQ pattern"}, {"q": "किस पादप हॉर्मोन को 'तनाव हॉर्मोन' (Stress hormone) कहा जाता है?\nWhich plant hormone is called the 'stress hormone'?", "o": ["ऑक्सिन / Auxin", "जिबरेलिन / Gibberellin", "साइटोकाइनिन / Cytokinin", "एब्सिसिक अम्ल / Abscisic acid"], "a": 3, "e": "ABA जल तनाव में रंध्र (stomata) बंद कराता है और सुप्तावस्था बढ़ाता है।\nABA closes stomata under water stress and promotes dormancy.", "s": "PHY", "lv": "Easy", "src": "Taiz & Zeiger, Plant Physiology and Development (Sinauer); Jain, Fundamentals of Plant Physiology", "cls": "New - PYQ pattern"}, {"q": "पृथ्वी पर सबसे अधिक मात्रा में पाया जाने वाला प्रोटीन है\nThe most abundant protein on Earth is", "o": ["कोलेजन / Collagen", "रुबिस्को / RuBisCO", "हीमोग्लोबिन / Haemoglobin", "केराटिन / Keratin"], "a": 1, "e": "RuBisCO (राइबुलोज-1,5-बिसफॉस्फेट कार्बोक्सिलेज़/ऑक्सीजिनेज़) पत्ती के घुलनशील प्रोटीन का बड़ा भाग है।\nRuBisCO forms a large part of soluble leaf protein and is the most abundant protein on Earth.", "s": "PHY", "lv": "Moderate", "src": "Taiz & Zeiger, Plant Physiology and Development (Sinauer); Jain, Fundamentals of Plant Physiology", "cls": "New - PYQ pattern"}, {"q": "'टौंग्या' (Taungya) कृषि वानिकी पद्धति की शुरुआत किस देश में हुई?\nThe 'Taungya' agroforestry system originated in", "o": ["भारत / India", "इंडोनेशिया / Indonesia", "केन्या / Kenya", "म्यांमार (बर्मा) / Myanmar (Burma)"], "a": 3, "e": "टौंग्या 1856 में बर्मा में डायट्रिच ब्रांडिस द्वारा सागौन रोपण के साथ शुरू हुई; भारत में 1890 के आसपास।\nTaungya began in Burma in 1856 under Dietrich Brandis with teak planting; introduced to India around 1890.", "s": "AGFOR", "lv": "Moderate", "src": "Nair, P.K.R., An Introduction to Agroforestry (ICRAF/Kluwer); ICAR-CAFRI, Jhansi", "cls": "New - PYQ pattern"}, {"q": "राजस्थान के शुष्क क्षेत्रों में कृषि वानिकी का प्रमुख वृक्ष 'खेजड़ी' का वानस्पतिक नाम है\nThe botanical name of 'khejri', a key agroforestry tree of arid Rajasthan, is", "o": ["Prosopis juliflora", "Acacia nilotica", "Prosopis cineraria", "Dalbergia sissoo"], "a": 2, "e": "खेजड़ी = Prosopis cineraria (राजस्थान का राज्य वृक्ष); विलायती बबूल = P. juliflora; देशी बबूल = Acacia nilotica।\nKhejri - Prosopis cineraria (state tree of Rajasthan); P. juliflora - mesquite; Acacia nilotica - babul.", "s": "AGFOR", "lv": "Easy", "src": "ICAR-CAZRI, Jodhpur", "cls": "New - PYQ pattern"}, {"q": "भारत में वृक्ष का व्यास 'छाती की ऊँचाई' (DBH) पर किस ऊँचाई पर मापा जाता है?\nIn India, tree diameter at breast height (DBH) is measured at", "o": ["1.00 m", "1.37 m", "1.50 m", "1.30 m"], "a": 1, "e": "भारत में breast height = भूमि से 1.37 m (4.5 फुट); कई यूरोपीय देश 1.30 m लेते हैं।\nIn India breast height is 1.37 m (4.5 ft) above ground; many European countries use 1.30 m.", "s": "AGFOR", "lv": "Moderate", "src": "Chaturvedi & Khanna, Forest Mensuration and Biometry", "cls": "New - PYQ pattern"}, {"q": "भारत में वन्यजीव संरक्षण अधिनियम किस वर्ष पारित हुआ?\nThe Wildlife (Protection) Act of India was enacted in", "o": ["1980", "1986", "1972", "2002"], "a": 2, "e": "वन्यजीव (संरक्षण) अधिनियम 1972; वन संरक्षण अधिनियम 1980; पर्यावरण संरक्षण अधिनियम 1986।\nWildlife (Protection) Act 1972; Forest (Conservation) Act 1980; Environment (Protection) Act 1986.", "s": "AGFOR", "lv": "Easy", "src": "MoEFCC (moef.gov.in) - Acts", "cls": "New - PYQ pattern"}, {"q": "'फसल-खरपतवार प्रतिस्पर्धा की क्रांतिक अवधि' का अर्थ है\nThe 'critical period of crop-weed competition' is", "o": ["फसल की पूरी अवधि / The entire crop duration", "वह न्यूनतम अवधि जिसमें खरपतवार नियंत्रण से उपज हानि रोकी जा सकती है / The shortest period during which weed control prevents yield loss", "केवल कटाई का समय / Only the harvesting time", "बुवाई से पहले का समय / The period before sowing"], "a": 1, "e": "यह वह समय है जिसमें खरपतवार-मुक्त रखने से उपज हानि नहीं होती; अधिकतर फसलों में अवधि का पहला लगभग एक-तिहाई भाग।\nIt is the shortest time span in which keeping the crop weed-free prevents yield loss; usually the first third of crop duration.", "s": "WEED", "lv": "Moderate", "src": "T.K. Das, Weed Science: Basics and Applications; ICAR-DWR", "cls": "New - PYQ pattern"}, {"q": "ग्लाइफोसेट (Glyphosate) किस एंजाइम को अवरुद्ध करता है?\nGlyphosate inhibits the enzyme", "o": ["ALS (एसिटोलैक्टेट सिंथेज़) / Acetolactate synthase", "ACCase", "EPSP सिंथेज़ / EPSP synthase", "प्रकाशतंत्र-II / Photosystem II"], "a": 2, "e": "ग्लाइफोसेट (अचयनात्मक, अंतःप्रवाही) शिकिमेट पथ के EPSPS को रोककर सुगंधित अमीनो अम्ल बनना बंद करता है।\nGlyphosate (non-selective, systemic) blocks EPSPS of the shikimate pathway, stopping aromatic amino acid synthesis.", "s": "WEED", "lv": "Moderate", "src": "HRAC/WSSA herbicide classification; T.K. Das, Weed Science", "cls": "New - PYQ pattern"}, {"q": "गाजर घास (Parthenium) के जैविक नियंत्रण के लिए प्रयुक्त मैक्सिकन भृंग है\nThe Mexican beetle used for biological control of Parthenium is", "o": ["Neochetina eichhorniae", "Cactoblastis cactorum", "Coccinella septempunctata", "Zygogramma bicolorata"], "a": 3, "e": "Zygogramma bicolorata = गाजर घास; Neochetina = जलकुंभी; Cactoblastis = नागफनी (Opuntia)।\nZygogramma bicolorata - Parthenium; Neochetina - water hyacinth; Cactoblastis - Opuntia.", "s": "WEED", "lv": "Easy", "src": "ICAR-DWR, Jabalpur (dwr.icar.gov.in)", "cls": "New - PYQ pattern"}, {"q": "एट्राज़ीन (Atrazine) शाकनाशी का सबसे अधिक उपयोग किस फसल में किया जाता है?\nAtrazine herbicide is most commonly used in", "o": ["मक्का / Maize", "गेहूँ / Wheat", "सोयाबीन / Soybean", "धान (नर्सरी) / Rice nursery"], "a": 0, "e": "एट्राज़ीन (ट्राइएज़ीन, PSII अवरोधक) मक्का व गन्ने में अंकुरण-पूर्व प्रयोग; मक्का इसे निष्क्रिय (detoxify) कर लेता है।\nAtrazine (triazine, PSII inhibitor) is applied pre-emergence in maize and sugarcane; maize detoxifies it.", "s": "WEED", "lv": "Moderate", "src": "T.K. Das, Weed Science; CIB&RC approved uses (ppqs.gov.in)", "cls": "New - PYQ pattern"}, {"q": "फार्म योजना में छोटे परिवर्तन (जैसे एक फसल के स्थान पर दूसरी) का लाभ आँकने के लिए प्रयुक्त बजट है\nThe budget used to assess the profitability of a minor change in the farm plan is", "o": ["पूर्ण बजट / Complete budget", "नकद बजट / Cash budget", "राष्ट्रीय बजट / National budget", "आंशिक बजट / Partial budget"], "a": 3, "e": "आंशिक बजट में केवल बदलने वाली लागत व आय (अतिरिक्त आय, घटी लागत बनाम घटी आय, अतिरिक्त लागत) देखी जाती है।\nA partial budget considers only changed costs and returns from a minor change.", "s": "ECO", "lv": "Moderate", "src": "Johl & Kapur, Fundamentals of Farm Business Management", "cls": "New - PYQ pattern"}, {"q": "कृषि मूल्य आयोग (जो बाद में CACP बना) की स्थापना किस वर्ष हुई?\nThe Agricultural Prices Commission (later CACP) was set up in", "o": ["1955", "1985", "1991", "1965"], "a": 3, "e": "1965 में कृषि मूल्य आयोग बना; 1985 में इसका नाम CACP हुआ।\nThe Agricultural Prices Commission was set up in 1965 and renamed CACP in 1985.", "s": "ECO", "lv": "Moderate", "src": "CACP (cacp.da.gov.in) - About us", "cls": "New - PYQ pattern"}, {"q": "राष्ट्रीय कृषि बाज़ार (e-NAM) की शुरुआत कब हुई?\nWhen was the National Agriculture Market (e-NAM) launched?", "o": ["14 अप्रैल 2016 / 14 April 2016", "1 जुलाई 2017 / 1 July 2017", "24 फरवरी 2019 / 24 February 2019", "2 अक्टूबर 2014 / 2 October 2014"], "a": 0, "e": "e-NAM 14 अप्रैल 2016 को शुरू हुआ; SFAC इसकी प्रमुख कार्यान्वयन एजेंसी है।\ne-NAM was launched on 14 April 2016; SFAC is the lead implementing agency.", "s": "ECO", "lv": "Easy", "src": "e-NAM (enam.gov.in)", "cls": "New - PYQ pattern"}, {"q": "कृषि लागत अवधारणाओं में Cost A1 में 'पट्टे पर ली गई भूमि का किराया' जोड़ने पर कौन-सी लागत बनती है?\nIn farm cost concepts, adding 'rent paid for leased-in land' to Cost A1 gives", "o": ["Cost B1", "Cost B2", "Cost C1", "Cost A2"], "a": 3, "e": "A2 = A1 + पट्टे की भूमि का किराया; B1 = A1 + स्वयं की स्थिर पूँजी पर ब्याज; B2 = B1 + स्वयं की भूमि का किराया मूल्य + पट्टे का किराया।\nA2 = A1 + rent on leased-in land; B1 = A1 + interest on owned fixed capital; B2 = B1 + rental value of owned land + rent on leased-in land.", "s": "ECO", "lv": "Moderate", "src": "CACP, Price Policy Reports - cost concepts (cacp.da.gov.in)", "cls": "New - PYQ pattern"}, {"q": "रोजर्स के नवाचार प्रसार मॉडल में 'प्रारंभिक अपनाने वाले' (Early adopters) कितने प्रतिशत होते हैं?\nIn Rogers' diffusion of innovations, early adopters make up", "o": ["2.5%", "13.5%", "34%", "16%"], "a": 1, "e": "नवाचारी 2.5%, प्रारंभिक अपनाने वाले 13.5%, प्रारंभिक बहुमत 34%, पश्चवर्ती बहुमत 34%, पिछड़े 16%।\nInnovators 2.5%, early adopters 13.5%, early majority 34%, late majority 34%, laggards 16%.", "s": "EXT", "lv": "Moderate", "src": "Rogers, E.M., Diffusion of Innovations; Ray, G.L., Extension Communication and Management", "cls": "New - PYQ pattern"}, {"q": "किसानों के खेत पर अग्रिम पंक्ति प्रदर्शन (Front Line Demonstrations) मुख्य रूप से कौन करता है?\nFront Line Demonstrations (FLDs) on farmers' fields are mainly conducted by", "o": ["कृषि विज्ञान केंद्र / Krishi Vigyan Kendras", "FCI / भारतीय खाद्य निगम", "NABARD", "सहकारी बैंक / Cooperative banks"], "a": 0, "e": "KVK के अधिदेश में तकनीकी आकलन (OFT) और अग्रिम पंक्ति प्रदर्शन (FLD) शामिल हैं।\nThe KVK mandate includes on-farm testing (OFT) and front line demonstrations (FLD).", "s": "EXT", "lv": "Easy", "src": "ICAR - KVK mandate (kvk.icar.gov.in)", "cls": "New - PYQ pattern"}, {"q": "प्रशिक्षण एवं भ्रमण (T&V) प्रसार प्रणाली किसने विकसित की?\nThe Training and Visit (T&V) extension system was developed by", "o": ["डैनियल बेनर / Daniel Benor", "एस.के. डे / S.K. Dey", "स्पेंसर हैच / Spencer Hatch", "एम.एस. रंधावा / M.S. Randhawa"], "a": 0, "e": "T&V प्रणाली डैनियल बेनर (विश्व बैंक) ने विकसित की; भारत में 1974 में राजस्थान (चंबल कमांड) व मध्य प्रदेश में शुरू हुई।\nThe T&V system was developed by Daniel Benor (World Bank); started in India in 1974 in Rajasthan (Chambal command) and MP.", "s": "EXT", "lv": "Moderate", "src": "Ray, G.L., Extension Communication and Management; Benor & Harrison (1977), World Bank", "cls": "New - PYQ pattern"}, {"q": "'विधि प्रदर्शन' (Method demonstration) का मुख्य उद्देश्य है किसानों को सिखाना\nThe main purpose of a method demonstration is to teach farmers", "o": ["कोई कार्य कैसे करें / How to do a task", "किसी तकनीक के परिणाम / The results of a technology", "बाज़ार भाव / Market prices", "सरकारी योजनाएँ / Government schemes"], "a": 0, "e": "विधि प्रदर्शन = 'कैसे करें' (कौशल); परिणाम प्रदर्शन = 'क्यों अपनाएँ' (परिणाम दिखाना)।\nMethod demonstration teaches 'how to do' (skill); result demonstration shows 'why' (results).", "s": "EXT", "lv": "Easy", "src": "Ray, G.L., Extension Communication and Management", "cls": "New - PYQ pattern"}, {"q": "1 अश्व शक्ति (British hp) लगभग कितने वाट के बराबर है?\n1 horsepower (British hp) is approximately equal to", "o": ["1,000 W", "500 W", "250 W", "746 W"], "a": 3, "e": "1 hp = 746 W (लगभग 0.746 kW)।\n1 hp = 746 W (about 0.746 kW).", "s": "ENGG", "lv": "Easy", "src": "Michael & Ojha, Principles of Agricultural Engineering, Vol. I & II", "cls": "New - PYQ pattern"}, {"q": "निम्नलिखित में से कौन-सी अवनालिका (Gully) नियंत्रण संरचना है?\nWhich of the following is a gully control structure?", "o": ["चेक डैम / Check dam", "समोच्च मेड़ / Contour bund", "पट्टीदार खेती / Strip cropping", "पलवार / Mulching"], "a": 0, "e": "चेक डैम अवनालिका में बहाव की गति घटाकर गाद रोकता है; समोच्च मेड़, पट्टीदार खेती, पलवार खेत-स्तरीय उपाय हैं।\nCheck dams reduce flow velocity and trap silt in gullies; the others are field-level measures.", "s": "ENGG", "lv": "Easy", "src": "Michael & Ojha, Principles of Agricultural Engineering, Vol. I & II; ICAR-IISWC, Dehradun", "cls": "New - PYQ pattern"}, {"q": "बायोगैस का मुख्य घटक कौन-सी गैस है?\nThe main constituent of biogas is", "o": ["कार्बन डाइऑक्साइड / Carbon dioxide", "हाइड्रोजन / Hydrogen", "मीथेन / Methane", "हाइड्रोजन सल्फाइड / Hydrogen sulphide"], "a": 2, "e": "बायोगैस में मीथेन लगभग 55-65% और CO2 लगभग 35-45% होती है।\nBiogas contains about 55-65% methane and 35-45% CO2.", "s": "ENGG", "lv": "Easy", "src": "MNRE (mnre.gov.in) - Biogas; Michael & Ojha, Principles of Agricultural Engineering, Vol. I & II", "cls": "New - PYQ pattern"}, {"q": "कंबाइन हार्वेस्टर कौन-से कार्य एक साथ करता है?\nA combine harvester performs which operations together?", "o": ["जुताई व बुवाई / Ploughing and sowing", "सिंचाई व छिड़काव / Irrigation and spraying", "कटाई, गहाई व सफाई / Reaping, threshing and cleaning", "केवल कटाई / Only reaping"], "a": 2, "e": "कंबाइन एक साथ फसल काटता, गहाई करता और दाने साफ़ करता है।\nA combine reaps, threshes and cleans grain in one pass.", "s": "ENGG", "lv": "Easy", "src": "Michael & Ojha, Principles of Agricultural Engineering, Vol. I & II", "cls": "New - PYQ pattern"}, {"q": "प्रमाणित बीज (Certified seed) के टैग का रंग होता है\nThe colour of the tag on certified seed is", "o": ["नीला (Azure blue) / Azure blue", "सुनहरा पीला / Golden yellow", "सफेद / White", "हरा / Green"], "a": 0, "e": "प्रजनक बीज = सुनहरा पीला; आधार बीज = सफेद; प्रमाणित बीज = नीला (Azure blue)।\nBreeder seed - golden yellow; foundation seed - white; certified seed - azure blue.", "s": "SEED", "lv": "Easy", "src": "Indian Minimum Seed Certification Standards (DAC&FW, 2013)", "cls": "New - PYQ pattern"}, {"q": "भारतीय न्यूनतम बीज प्रमाणन मानकों के अनुसार गेहूँ के प्रमाणित बीज का न्यूनतम अंकुरण होना चाहिए\nAs per Indian Minimum Seed Certification Standards, the minimum germination for certified wheat seed is", "o": ["75%", "80%", "90%", "85%"], "a": 3, "e": "गेहूँ (आधार व प्रमाणित) बीज: न्यूनतम अंकुरण 85%, भौतिक शुद्धता 98%।\nWheat (foundation and certified): minimum germination 85%, physical purity 98%.", "s": "SEED", "lv": "Moderate", "src": "Indian Minimum Seed Certification Standards (DAC&FW, 2013) - Wheat", "cls": "New - PYQ pattern"}, {"q": "टेट्राज़ोलियम (TZ) परीक्षण से बीज का कौन-सा गुण ज्ञात होता है?\nThe tetrazolium (TZ) test determines seed", "o": ["नमी / Moisture", "शुद्धता / Purity", "जीवनक्षमता / Viability", "भार / Weight"], "a": 2, "e": "जीवित ऊतकों के डिहाइड्रोजिनेज़ एंजाइम TZ को लाल फॉर्मेज़ान में बदलते हैं, अतः लाल रंग = जीवित बीज।\nDehydrogenases in living tissue reduce TZ to red formazan; red staining indicates viable seed.", "s": "SEED", "lv": "Easy", "src": "ISTA Rules (seedtest.org); Agrawal, P.K., Seed Technology", "cls": "New - PYQ pattern"}, {"q": "TRIPS समझौते के अनुच्छेद 27.3(b) के अंतर्गत भारत ने पौधा किस्मों के संरक्षण हेतु कौन-सी 'सुई जेनेरिस' (sui generis) प्रणाली अपनाई?\nUnder Article 27.3(b) of TRIPS, which sui generis system did India adopt for protecting plant varieties?", "o": ["पेटेंट अधिनियम 1970 / Patents Act 1970", "PPV&FR अधिनियम 2001 / PPV&FR Act 2001", "बीज अधिनियम 1966 / Seeds Act 1966", "भौगोलिक संकेत अधिनियम 1999 / GI Act 1999"], "a": 1, "e": "TRIPS पौधा किस्मों का संरक्षण पेटेंट या प्रभावी sui generis प्रणाली से माँगता है; भारत ने PPV&FR अधिनियम 2001 बनाया जिसमें कृषक अधिकार भी हैं।\nTRIPS requires protection by patents or an effective sui generis system; India enacted the PPV&FR Act 2001, which also includes farmers' rights.", "s": "SEED", "lv": "Moderate", "src": "WTO TRIPS Agreement, Art. 27.3(b) (wto.org); PPV&FR Authority", "cls": "New - PYQ pattern"}, {"q": "फॉस्फोरस मृदा से जड़ की सतह तक मुख्य रूप से किस प्रक्रिया से पहुँचता है?\nPhosphorus reaches the root surface mainly by", "o": ["जलप्रवाह (Mass flow) / Mass flow", "विसरण / Diffusion", "जड़ अवरोधन / Root interception", "वाष्पोत्सर्जन / Transpiration"], "a": 1, "e": "P और K मुख्यतः विसरण से; नाइट्रेट, Ca, Mg, S अधिकतर जलप्रवाह (mass flow) से जड़ तक पहुँचते हैं।\nP and K move mainly by diffusion; nitrate, Ca, Mg and S mostly by mass flow.", "s": "PNUT", "lv": "Moderate", "src": "Marschner's Mineral Nutrition of Higher Plants; Indian Society of Soil Science, Fundamentals of Soil Science (ISSS, New Delhi); Brady & Weil, The Nature and Properties of Soils", "cls": "New - PYQ pattern"}, {"q": "नाइट्रोजन की कमी के लक्षण सबसे पहले कहाँ दिखाई देते हैं?\nNitrogen deficiency symptoms first appear on", "o": ["नई पत्तियों पर / Young leaves", "फूलों पर / Flowers", "जड़ों पर / Roots", "पुरानी (निचली) पत्तियों पर / Old (lower) leaves"], "a": 3, "e": "N पौधे में गतिशील है, अतः पुरानी पत्तियों से नई पत्तियों में चला जाता है और पुरानी पत्तियाँ पहले पीली होती हैं।\nN is mobile in the plant and moves to young leaves, so older leaves turn yellow first.", "s": "PNUT", "lv": "Easy", "src": "Marschner's Mineral Nutrition of Higher Plants; Taiz & Zeiger, Plant Physiology and Development (Sinauer); Jain, Fundamentals of Plant Physiology", "cls": "New - PYQ pattern"}, {"q": "सामान्य वायुमंडलीय दाब पर शुद्ध जल का जल विभव (Water potential) होता है\nThe water potential of pure water at atmospheric pressure is", "o": ["शून्य / Zero", "धनात्मक / Positive", "ऋणात्मक / Negative", "अनंत / Infinite"], "a": 0, "e": "शुद्ध जल का ψ = 0 (अधिकतम); विलेय मिलाने पर ψ ऋणात्मक हो जाता है।\nPure water has ψ = 0 (the maximum); adding solutes makes it negative.", "s": "PNUT", "lv": "Easy", "src": "Taiz & Zeiger, Plant Physiology and Development (Sinauer); Jain, Fundamentals of Plant Physiology", "cls": "New - PYQ pattern"}, {"q": "नई पत्तियों में शिराओं के बीच हरिमाहीनता (Interveinal chlorosis) किस पोषक तत्व की कमी का लक्षण है?\nInterveinal chlorosis in young leaves is a symptom of deficiency of", "o": ["नाइट्रोजन / Nitrogen", "लोहा / Iron", "पोटैशियम / Potassium", "मैग्नीशियम / Magnesium"], "a": 1, "e": "Fe पौधे में अगतिशील है, अतः कमी नई पत्तियों में शिराओं के बीच पीलेपन के रूप में; Mg की कमी पुरानी पत्तियों में।\nFe is immobile, so deficiency shows as interveinal chlorosis in young leaves; Mg deficiency appears on older leaves.", "s": "PNUT", "lv": "Moderate", "src": "Marschner's Mineral Nutrition of Higher Plants; Indian Society of Soil Science, Fundamentals of Soil Science (ISSS, New Delhi); Brady & Weil, The Nature and Properties of Soils", "cls": "New - PYQ pattern"}, {"q": "दूध के HTST पाश्चुरीकरण में सामान्य ताप-समय संयोजन है\nThe usual temperature-time combination for HTST pasteurisation of milk is", "o": ["72 °C, 15 सेकंड / 72 °C for 15 s", "63 °C, 30 मिनट / 63 °C for 30 min", "135 °C, 2 सेकंड / 135 °C for 2 s", "100 °C, 10 मिनट / 100 °C for 10 min"], "a": 0, "e": "HTST = 71.7-72 °C पर 15 s; LTLT (होल्डिंग) = 63 °C पर 30 min; UHT = 135-150 °C पर 2-4 s।\nHTST 71.7-72 °C for 15 s; LTLT 63 °C for 30 min; UHT 135-150 °C for 2-4 s.", "s": "FOOD", "lv": "Moderate", "src": "FSSAI, Food Safety and Standards (Food Products Standards) Regulations; Srilakshmi, Food Science (New Age); Frazier & Westhoff, Food Microbiology", "cls": "New - PYQ pattern"}, {"q": "अधिकांश जीवाणुओं की वृद्धि के लिए न्यूनतम जल सक्रियता (aw) लगभग कितनी चाहिए?\nMost bacteria require a minimum water activity (aw) of about", "o": ["0.60", "0.70", "0.91", "0.50"], "a": 2, "e": "अधिकांश जीवाणु aw 0.91 से ऊपर बढ़ते हैं; यीस्ट लगभग 0.88; फफूँद लगभग 0.80; 0.60 से नीचे सूक्ष्मजीव वृद्धि नहीं।\nMost bacteria grow above aw 0.91; yeasts about 0.88; moulds about 0.80; no microbial growth below 0.60.", "s": "FOOD", "lv": "Moderate", "src": "Srilakshmi, Food Science (New Age); Frazier & Westhoff, Food Microbiology", "cls": "New - PYQ pattern"}, {"q": "'प्रोबायोटिक्स' (Probiotics) क्या हैं?\nWhat are probiotics?", "o": ["अपचनीय रेशे जो लाभकारी जीवाणुओं का भोजन हैं / Non-digestible fibres that feed good bacteria", "कृत्रिम परिरक्षक / Synthetic preservatives", "एंटीबायोटिक दवाएँ / Antibiotic drugs", "जीवित सूक्ष्मजीव जो पर्याप्त मात्रा में लेने पर स्वास्थ्य लाभ देते हैं / Live micro-organisms that give health benefits when taken in adequate amounts"], "a": 3, "e": "प्रोबायोटिक = जीवित लाभकारी सूक्ष्मजीव (Lactobacillus, Bifidobacterium); प्रीबायोटिक = अपचनीय रेशा (जैसे इनुलिन)।\nProbiotics are live beneficial microbes (Lactobacillus, Bifidobacterium); prebiotics are non-digestible fibres (e.g. inulin).", "s": "FOOD", "lv": "Easy", "src": "FAO/WHO (2002), Guidelines for the Evaluation of Probiotics in Food; FSSAI Nutraceutical Regulations", "cls": "New - PYQ pattern"}, {"q": "राष्ट्रीय खाद्य सुरक्षा अधिनियम (NFSA) 2013 के तहत प्राथमिकता परिवारों को प्रति व्यक्ति प्रति माह कितना खाद्यान्न मिलता है?\nUnder NFSA 2013, priority households get how much foodgrain per person per month?", "o": ["2 kg", "10 kg", "5 kg", "35 kg"], "a": 2, "e": "प्राथमिकता परिवार = 5 kg प्रति व्यक्ति प्रति माह; अंत्योदय (AAY) = 35 kg प्रति परिवार प्रति माह।\nPriority households - 5 kg per person per month; AAY - 35 kg per household per month.", "s": "FSEC", "lv": "Easy", "src": "National Food Security Act, 2013, Section 3 (dfpd.gov.in)", "cls": "New - PYQ pattern"}, {"q": "अंत्योदय अन्न योजना (AAY) के अंतर्गत प्रत्येक परिवार को प्रति माह कितना खाद्यान्न मिलता है?\nUnder the Antyodaya Anna Yojana (AAY), each household gets how much foodgrain per month?", "o": ["20 kg", "25 kg", "35 kg", "50 kg"], "a": 2, "e": "AAY (दिसंबर 2000 से) परिवारों को 35 kg प्रति परिवार प्रति माह; NFSA 2013 में भी यही पात्रता रखी गई।\nAAY households (since Dec 2000) get 35 kg per household per month; NFSA 2013 retained this entitlement.", "s": "FSEC", "lv": "Easy", "src": "National Food Security Act, 2013; Department of Food & Public Distribution (dfpd.gov.in)", "cls": "New - PYQ pattern"}, {"q": "घेंघा (Goitre) रोग किस सूक्ष्म पोषक तत्व की कमी से होता है?\nGoitre is caused by deficiency of", "o": ["लोहा / Iron", "जस्ता / Zinc", "आयोडीन / Iodine", "विटामिन A / Vitamin A"], "a": 2, "e": "आयोडीन की कमी से थायरॉइड ग्रंथि बढ़ जाती है (घेंघा); लोहे की कमी = एनीमिया; विटामिन A की कमी = रतौंधी।\nIodine deficiency enlarges the thyroid (goitre); iron - anaemia; vitamin A - night blindness.", "s": "FSEC", "lv": "Easy", "src": "ICMR-NIN, Dietary Guidelines for Indians (2024); WHO", "cls": "New - PYQ pattern"}, {"q": "पादप आनुवंशिक अभियांत्रिकी में जीन स्थानांतरण के लिए प्रयुक्त 'Ti प्लाज्मिड' किस जीवाणु से प्राप्त होता है?\nThe 'Ti plasmid' used for gene transfer in plants comes from", "o": ["Escherichia coli", "Agrobacterium tumefaciens", "Bacillus thuringiensis", "Rhizobium leguminosarum"], "a": 1, "e": "Agrobacterium tumefaciens का Ti (Tumour-inducing) प्लाज्मिड T-DNA को पादप जीनोम में स्थानांतरित करता है।\nThe Ti (tumour-inducing) plasmid of Agrobacterium tumefaciens transfers T-DNA into the plant genome.", "s": "BIOT", "lv": "Easy", "src": "H.S. Chawla, Introduction to Plant Biotechnology; NCERT Biology Class XII", "cls": "New - PYQ pattern"}, {"q": "PCR में प्रयुक्त ताप-सहिष्णु Taq DNA पॉलीमरेज़ किस जीव से प्राप्त होता है?\nThe heat-stable Taq DNA polymerase used in PCR is obtained from", "o": ["Thermus aquaticus", "Escherichia coli", "Pyrococcus furiosus", "Saccharomyces cerevisiae"], "a": 0, "e": "Taq = Thermus aquaticus (गर्म झरनों का जीवाणु); Pfu पॉलीमरेज़ = Pyrococcus furiosus।\nTaq is from Thermus aquaticus (a hot-spring bacterium); Pfu polymerase is from Pyrococcus furiosus.", "s": "BIOT", "lv": "Easy", "src": "NCERT Biology Class XII, Biotechnology: Principles and Processes", "cls": "New - PYQ pattern"}, {"q": "बायोइन्फॉर्मेटिक्स में 'BLAST' का प्रयोग किसके लिए होता है?\nIn bioinformatics, 'BLAST' is used for", "o": ["अनुक्रम समानता खोज / Sequence similarity search", "प्रोटीन क्रिस्टलीकरण / Protein crystallisation", "DNA विलगन / DNA isolation", "कोशिका संवर्धन / Cell culture"], "a": 0, "e": "BLAST (Basic Local Alignment Search Tool, NCBI) किसी अनुक्रम को डेटाबेस से मिलाकर समान अनुक्रम खोजता है।\nBLAST (NCBI) compares a query sequence against databases to find similar sequences.", "s": "BIOT", "lv": "Moderate", "src": "NCBI (ncbi.nlm.nih.gov/blast); Altschul et al. (1990), J. Mol. Biol. 215: 403-410", "cls": "New - PYQ pattern"}, {"q": "डिब्बाबंद भोजन में 'बोटुलिज़्म' (Botulism) विषाक्तता किस जीवाणु से होती है?\nBotulism poisoning from canned food is caused by", "o": ["Salmonella typhi", "Staphylococcus aureus", "Clostridium botulinum", "Escherichia coli"], "a": 2, "e": "Clostridium botulinum अवायवीय, बीजाणु बनाने वाला जीवाणु है; कम अम्लीय डिब्बाबंद भोजन में न्यूरोटॉक्सिन बनाता है।\nClostridium botulinum is an anaerobic spore-former that produces neurotoxin in low-acid canned foods.", "s": "FMIC", "lv": "Easy", "src": "Srilakshmi, Food Science (New Age); Frazier & Westhoff, Food Microbiology", "cls": "New - PYQ pattern"}, {"q": "'मैलार्ड अभिक्रिया' (Maillard reaction) किनके बीच होती है?\nThe Maillard reaction takes place between", "o": ["वसा व ऑक्सीजन / Fat and oxygen", "अपचायी शर्करा व अमीनो अम्ल / Reducing sugar and amino acid", "एंजाइम व फ़ीनॉल / Enzyme and phenol", "विटामिन C व धातु / Vitamin C and metal"], "a": 1, "e": "मैलार्ड = अपचायी शर्करा + अमीनो समूह की गैर-एंजाइमी भूरापन अभिक्रिया (ब्रेड की परत, भुनी कॉफी); पॉलीफ़ीनॉल ऑक्सीडेज़ = एंजाइमी भूरापन।\nMaillard is non-enzymatic browning between reducing sugars and amino groups (bread crust, roasted coffee); polyphenol oxidase causes enzymatic browning.", "s": "FMIC", "lv": "Moderate", "src": "Srilakshmi, Food Science (New Age); Frazier & Westhoff, Food Microbiology; Fennema's Food Chemistry", "cls": "New - PYQ pattern"}, {"q": "भारतीय खाद्य सुरक्षा एवं मानक प्राधिकरण (FSSAI) किस अधिनियम के अंतर्गत स्थापित है?\nFSSAI has been established under which Act?", "o": ["खाद्य अपमिश्रण निवारण अधिनियम, 1954 / PFA Act, 1954", "खाद्य सुरक्षा एवं मानक अधिनियम, 2006 / Food Safety and Standards Act, 2006", "आवश्यक वस्तु अधिनियम, 1955 / Essential Commodities Act, 1955", "उपभोक्ता संरक्षण अधिनियम, 2019 / Consumer Protection Act, 2019"], "a": 1, "e": "FSS अधिनियम 2006 के अंतर्गत FSSAI 2008 में स्थापित हुआ; इसने PFA अधिनियम 1954 सहित कई कानूनों को समेकित किया।\nFSSAI was set up in 2008 under the FSS Act 2006, which consolidated earlier laws including the PFA Act 1954.", "s": "FMIC", "lv": "Easy", "src": "FSSAI (fssai.gov.in) - About FSSAI", "cls": "New - PYQ pattern"}]}]);
